           to_varchar(coalesce(nullif(trim(to_varchar("AADHAAR_ENROLLMENT_NO")), ''), nullif(trim(to_varchar("ABHA_ID")), ''), nullif(trim(to_varchar("EXISTING_PARTNER_ID")), ''), nullif(trim(to_varchar("HOSPITAL_ID")), ''), nullif(trim(to_varchar("IDENTIFIER")), ''), nullif(trim(to_varchar("ID_NUMBER")), ''), nullif(trim(to_varchar("PARTNER_REF")), ''), nullif(trim(to_varchar("REGISTRATION_NO")), ''), nullif(trim(to_varchar("SEPZ_REGISTRATION_NO")), ''), nullif(trim(to_varchar("SEZ_REGISTRATION_NO")), ''), nullif(trim(to_varchar("SERVICE_TAX_NO")), ''), nullif(trim(to_varchar("ROHINI_CODE")), ''), nullif(trim(to_varchar("VID")), ''))) as "IDENTIFICATIONNUMBER",
           to_varchar(coalesce(nullif(trim(to_varchar("IDENTIFICATION_PROOF")), ''), nullif(trim(to_varchar("ID_TYPE")), ''), nullif(trim(to_varchar("ID_TYPE1")), ''))) as "IDENTIFICATIONTYPECODE",
           to_varchar(coalesce(nullif(trim(to_varchar("CLAIM_POA_STATUS")), ''), nullif(trim(to_varchar("CLAIM_POI_STATUS")), ''), nullif(trim(to_varchar("E_INSURANCE_DEMAT_ACCOUNT_VERIFIED")), ''), nullif(trim(to_varchar("POA_DRIVING_LICENSE_STATUS")), ''), nullif(trim(to_varchar("POA_NREGA_JOB_CARD_STATUS")), ''), nullif(trim(to_varchar("POA_PASSPORT_STATUS")), ''))) as "IDENTIFICATIONVERIFIEDINDICATOR",
           to_varchar(nullif(trim(to_varchar("INSURANCE_REPOSITORY_CODE")), '')) as "INSURANCEREPOSITORYNAME",
           to_varchar(nullif(trim(to_varchar("NREGA_JOB_CARD")), '')) as "NREGACARDNUMBER",
           to_varchar(nullif(trim(to_varchar("PROOF_OF_ADDRESS_SUBMITTED_FOR_CURRENT_PERMANENT_OVERSEAS_ADDRESS")), '')) as "OVDCATEGORY",
           to_varchar(nullif(trim(to_varchar("PAN_NO")), '')) as "PANNUMBER",
           to_varchar(nullif(trim(to_varchar("POI_PAN_CARD_STATUS")), '')) as "PANVERIFICATIONSTATUS",
           to_varchar(nullif(trim(to_varchar("PASSPORT_EXPIRY_DATE")), '')) as "PASSPORTEXPIRYDATE",
           to_varchar(nullif(trim(to_varchar("PASSPORT_NUMBER")), '')) as "PASSPORTNUMBER",
           to_varchar(nullif(trim(to_varchar("TAN_NUMBER")), '')) as "TANNUMBER",
           to_varchar(nullif(trim(to_varchar("VOTER_ID")), '')) as "VOTERIDNUMBER",
           to_varchar(nullif(trim(to_varchar("CKYC_NUMBER")), '')) as "CKYCNUMBER"
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
    ) where hkey in (select hkey from sample_keys)
),
src_tbl as (
    -- sat_multi_source OBJECT branch: one value per (key, source table), then one row per key
    select hkey, regexp_replace(rs, '^MAXIMUS_', '') as source_table, max(ldts) as ldts,
           max("AADHAARNUMBER") as "AADHAARNUMBER",
           max("AADHAARVERIFICATIONSTATUS") as "AADHAARVERIFICATIONSTATUS",
           max("AGEPROOFTYPE") as "AGEPROOFTYPE",
           max("CINNUMBER") as "CINNUMBER",
           max("DRIVINGLICENCEEXPIRYDATE") as "DRIVINGLICENCEEXPIRYDATE",
           max("DRIVINGLICENCENUMBER") as "DRIVINGLICENCENUMBER",
           max("EIANUMBER") as "EIANUMBER",
           max("FORM60INDICATOR") as "FORM60INDICATOR",
           max("GSTIN") as "GSTIN",
           max("GSTREGISTRATIONSTATUS") as "GSTREGISTRATIONSTATUS",
           max("GSTTAXPAYERTYPE") as "GSTTAXPAYERTYPE",
           max("IDENTIFICATIONEXPIRYDATE") as "IDENTIFICATIONEXPIRYDATE",
           max("IDENTIFICATIONISSUEDATE") as "IDENTIFICATIONISSUEDATE",
           max("IDENTIFICATIONISSUINGAUTHORITY") as "IDENTIFICATIONISSUINGAUTHORITY",
           max("IDENTIFICATIONNUMBER") as "IDENTIFICATIONNUMBER",
           max("IDENTIFICATIONTYPECODE") as "IDENTIFICATIONTYPECODE",
           max("IDENTIFICATIONVERIFIEDINDICATOR") as "IDENTIFICATIONVERIFIEDINDICATOR",
           max("INSURANCEREPOSITORYNAME") as "INSURANCEREPOSITORYNAME",
           max("NREGACARDNUMBER") as "NREGACARDNUMBER",
           max("OVDCATEGORY") as "OVDCATEGORY",
           max("PANNUMBER") as "PANNUMBER",
           max("PANVERIFICATIONSTATUS") as "PANVERIFICATIONSTATUS",
           max("PASSPORTEXPIRYDATE") as "PASSPORTEXPIRYDATE",
           max("PASSPORTNUMBER") as "PASSPORTNUMBER",
           max("TANNUMBER") as "TANNUMBER",
           max("VOTERIDNUMBER") as "VOTERIDNUMBER",
           max("CKYCNUMBER") as "CKYCNUMBER"
      from src_rows
     group by hkey, source_table
),
src as (
    select hkey, 'MAXIMUS' as rs_key, max(ldts) as ldts,
           object_construct_keep_null(
               'AADHAARNUMBER', to_varchar(object_agg(source_table, to_variant("AADHAARNUMBER"))),
               'GSTIN', to_varchar(object_agg(source_table, to_variant("GSTIN"))),
               'PANNUMBER', to_varchar(object_agg(source_table, to_variant("PANNUMBER"))),
               'PASSPORTNUMBER', to_varchar(object_agg(source_table, to_variant("PASSPORTNUMBER"))),
               'VOTERIDNUMBER', to_varchar(object_agg(source_table, to_variant("VOTERIDNUMBER"))),
               'CKYCNUMBER', to_varchar(object_agg(source_table, to_variant("CKYCNUMBER"))),
               'AADHAARVERIFICATIONSTATUS', max("AADHAARVERIFICATIONSTATUS"),
               'AGEPROOFTYPE', max("AGEPROOFTYPE"),
               'CINNUMBER', max("CINNUMBER"),
               'DRIVINGLICENCEEXPIRYDATE', max("DRIVINGLICENCEEXPIRYDATE"),
               'DRIVINGLICENCENUMBER', max("DRIVINGLICENCENUMBER"),
               'EIANUMBER', max("EIANUMBER"),
               'FORM60INDICATOR', max("FORM60INDICATOR"),
               'GSTREGISTRATIONSTATUS', max("GSTREGISTRATIONSTATUS"),
               'GSTTAXPAYERTYPE', max("GSTTAXPAYERTYPE"),
               'IDENTIFICATIONEXPIRYDATE', max("IDENTIFICATIONEXPIRYDATE"),
               'IDENTIFICATIONISSUEDATE', max("IDENTIFICATIONISSUEDATE"),
               'IDENTIFICATIONISSUINGAUTHORITY', max("IDENTIFICATIONISSUINGAUTHORITY"),
               'IDENTIFICATIONNUMBER', max("IDENTIFICATIONNUMBER"),
               'IDENTIFICATIONTYPECODE', max("IDENTIFICATIONTYPECODE"),
               'IDENTIFICATIONVERIFIEDINDICATOR', max("IDENTIFICATIONVERIFIEDINDICATOR"),
               'INSURANCEREPOSITORYNAME', max("INSURANCEREPOSITORYNAME"),
               'NREGACARDNUMBER', max("NREGACARDNUMBER"),
               'OVDCATEGORY', max("OVDCATEGORY"),
               'PANVERIFICATIONSTATUS', max("PANVERIFICATIONSTATUS"),
               'PASSPORTEXPIRYDATE', max("PASSPORTEXPIRYDATE"),
               'TANNUMBER', max("TANNUMBER")
           ) as obj
      from src_tbl
     group by hkey
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'MAXIMUS' as project, 'SAT_PARTY_IDENTIFICATION' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 34. MAXIMUS — SAT_PARTY_IDENTITY   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 17 column(s) compared. 2 RAW branch(es):
-- BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL,
-- BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'AGE', to_varchar(s."AGE"),
               'COUNTRYOFBIRTH', to_varchar(s."COUNTRYOFBIRTH"),
               'COUNTRYOFRESIDENCE', to_varchar(s."COUNTRYOFRESIDENCE"),
               'DATEOFBIRTH', to_varchar(s."DATEOFBIRTH"),
               'DATEOFDEATH', to_varchar(s."DATEOFDEATH"),
               'FIRSTNAME', to_varchar(s."FIRSTNAME"),
               'GENDERCODE', to_varchar(s."GENDERCODE"),
               'LASTNAME', to_varchar(s."LASTNAME"),
               'MIDDLENAME', to_varchar(s."MIDDLENAME"),
               'NATIONALITY', to_varchar(s."NATIONALITY"),
               'PARTYFULLNAME', to_varchar(s."PARTYFULLNAME"),
               'PARTYLEGALNAME', to_varchar(s."PARTYLEGALNAME"),
               'PARTYORIGINATIONDATE', to_varchar(s."PARTYORIGINATIONDATE"),
               'PARTYSTATUS', to_varchar(s."PARTYSTATUS"),
               'PARTYSUBTYPECODE', to_varchar(s."PARTYSUBTYPECODE"),
               'PARTYTYPECODE', to_varchar(s."PARTYTYPECODE"),
               'SALUTATION', to_varchar(s."SALUTATION")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY s
     where startswith(s.RECORD_SOURCE, 'MAXIMUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL  via stg2_mp__pd <- stg_maximus__pd
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim(to_varchar("PARTY_CODE")), ''))) AS VARCHAR))), '')) as hkey,
           'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL' as rs_key,
           ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'AGE', to_varchar(null),
               'COUNTRYOFBIRTH', to_varchar(null),
               'COUNTRYOFRESIDENCE', to_varchar(null),
               'DATEOFBIRTH', to_varchar(nullif(trim(to_varchar("DATE_OF_BIRTH")), '')),
               'DATEOFDEATH', to_varchar(null),
               'FIRSTNAME', to_varchar(nullif(trim(to_varchar("FIRST_NAME")), '')),
               'GENDERCODE', to_varchar(nullif(trim(to_varchar("GENDER")), '')),
               'LASTNAME', to_varchar(nullif(trim(to_varchar("LAST_NAME")), '')),
               'MIDDLENAME', to_varchar(nullif(trim(to_varchar("MIDDLE_NAME")), '')),
               'NATIONALITY', to_varchar(nullif(trim(to_varchar("NATIONALITY")), '')),
               'PARTYFULLNAME', to_varchar(null),
               'PARTYLEGALNAME', to_varchar(nullif(trim(to_varchar("BUSINESS_NAME")), '')),
               'PARTYORIGINATIONDATE', to_varchar(nullif(trim(to_varchar("PARTY_START_DATE")), '')),
               'PARTYSTATUS', to_varchar(nullif(trim(to_varchar("PARTY_STATUS")), '')),
               'PARTYSUBTYPECODE', to_varchar(null),
               'PARTYTYPECODE', to_varchar(nullif(trim(to_varchar("TYPE_OF_PARTY")), '')),
               'SALUTATION', to_varchar(nullif(trim(to_varchar("TITLE")), ''))
           ) as obj
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW  via stg2_mp__pd_prop_sp_pv <- stg_maximus__pd_prop_sp_pv
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
           'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as rs_key,
           ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'AGE', to_varchar(nullif(trim(to_varchar("AGE")), '')),
               'COUNTRYOFBIRTH', to_varchar(nullif(trim(to_varchar("COUNTRY_OF_BIRTH")), '')),
               'COUNTRYOFRESIDENCE', to_varchar(nullif(trim(to_varchar("COUNTRY_OF_RESIDENCE")), '')),
               'DATEOFBIRTH', to_varchar(nullif(trim(to_varchar("DATE_OF_BIRTH")), '')),
               'DATEOFDEATH', to_varchar(nullif(trim(to_varchar("DATE_OF_DEATH")), '')),
               'FIRSTNAME', to_varchar(nullif(trim(to_varchar("FIRST_NAME")), '')),
               'GENDERCODE', to_varchar(nullif(trim(to_varchar("GENDER")), '')),
               'LASTNAME', to_varchar(nullif(trim(to_varchar("LAST_NAME")), '')),
               'MIDDLENAME', to_varchar(nullif(trim(to_varchar("MIDDLE_NAME")), '')),
               'NATIONALITY', to_varchar(nullif(trim(to_varchar("NATIONALITY")), '')),
               'PARTYFULLNAME', to_varchar(coalesce(nullif(trim(to_varchar("BAGIC_EMPLOYEE_NAME")), ''), nullif(trim(to_varchar("BENEFICIARY_NAME")), ''), nullif(trim(to_varchar("HOSPITAL_NAME")), ''))),
               'PARTYLEGALNAME', to_varchar(nullif(trim(to_varchar("FIRMS_NAME")), '')),
               'PARTYORIGINATIONDATE', to_varchar(nullif(trim(to_varchar("CREATION_DATE")), '')),
               'PARTYSTATUS', to_varchar(null),
               'PARTYSUBTYPECODE', to_varchar(nullif(trim(to_varchar("PARTNER_TYPE")), '')),
               'PARTYTYPECODE', to_varchar(null),
               'SALUTATION', to_varchar(null)
           ) as obj
      from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'MAXIMUS' as project, 'SAT_PARTY_IDENTITY' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
