    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_AGREEMENT_COMMERCIAL_TERMS' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 100. OPUS — SAT_AGREEMENT_DEFINITION   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 1 column(s) compared. 1 RAW branch(es): BJAZ_INTERMEDIARY.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.AGREEMENT_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'AGREEMENTTYPE', to_varchar(s."AGREEMENTTYPE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AGREEMENT_DEFINITION s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BJAZ_INTERMEDIARY  via stg2_sat_bjaz_intermediary__agreement_definition <- stg_partner__bjaz_intermediary
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_AGREEMENT|' || (nullif(trim("INTERMEDIARY_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_INTERMEDIARY' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'AGREEMENTTYPE', to_varchar(nullif(trim("NATURE_OF_AGREEMENT"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_INTERMEDIARY
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_AGREEMENT_DEFINITION' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 101. OPUS — SAT_COMMON_ADDRESS   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 11 column(s) compared. 2 RAW branch(es): stitch
-- stitch_common_address, stitch stitch_kyc_common_address. stitch_common_address
-- reproduced from 5 RAW tables with no watermark window; every row combination per key
-- is kept because the stitch keeps one of them arbitrarily. stitch_kyc_common_address
-- reproduced from 8 RAW tables with no watermark window; every row combination per key
-- is kept because the stitch keeps one of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.LOCATION_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ADDRESSLINE1', to_varchar(s."ADDRESSLINE1"),
               'ADDRESSLINE2', to_varchar(s."ADDRESSLINE2"),
               'ADDRESSLINE3', to_varchar(s."ADDRESSLINE3"),
               'BUILDINGNAME', to_varchar(s."BUILDINGNAME"),
               'CITY', to_varchar(s."CITY"),
               'COUNTRYCODE', to_varchar(s."COUNTRYCODE"),
               'COUNTRYNAME', to_varchar(s."COUNTRYNAME"),
               'DOORNUMBER', to_varchar(s."DOORNUMBER"),
               'POSTALCODE', to_varchar(s."POSTALCODE"),
               'STATENAME', to_varchar(s."STATENAME"),
               'STREETNAME', to_varchar(s."STREETNAME")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_common_address: every key of every contributing table (no watermark window)
    select nullif(trim("ADD_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_ADDRESS_EXTN
     where nullif(trim("ADD_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("BILLING_LOC"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where nullif(trim("BILLING_LOC"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("BILLING_LOC"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PINCODE"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PINCODE"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("ADD_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_ADDRESSES
     where nullif(trim("ADD_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_AZBJ_ADDRESS_EXTN
    select distinct nullif(trim("ADD_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("ADDRESS_LINE6"::varchar), ''))), '') as "ADDRESSLINE2",
           nullif(trim(to_varchar(nullif(trim("ADDRESS_LINE7"::varchar), ''))), '') as "ADDRESSLINE3",
           nullif(trim(to_varchar(nullif(trim("BUILDING_NAME"::varchar), ''))), '') as "BUILDINGNAME",
           nullif(trim(to_varchar(nullif(trim("RESIDENCE_COUNTRY"::varchar), ''))), '') as "COUNTRYNAME",
           nullif(trim(to_varchar(nullif(trim("DOOR_NO"::varchar), ''))), '') as "DOORNUMBER",
           nullif(trim(to_varchar(nullif(trim("PLOT_STREET_NO"::varchar), ''))), '') as "STREETNAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_ADDRESS_EXTN
     where nullif(trim("ADD_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t1 as (
    -- OPUS_BJAZ_CLM_SUPP_EXTN
    select distinct nullif(trim("BILLING_LOC"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("PARENT_CO_ADD_LINE1"::varchar), ''))), '') as "ADDRESSLINE1",
           nullif(trim(to_varchar(nullif(trim("PARENT_CO_ADD_LINE2"::varchar), ''))), '') as "ADDRESSLINE2",
           nullif(trim(to_varchar(nullif(trim("PARENT_CO_ADD_LINE3"::varchar), ''))), '') as "ADDRESSLINE3",
           nullif(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), ''))), '') as "COUNTRYCODE",
           nullif(trim(to_varchar(nullif(trim("COUNTRY"::varchar), ''))), '') as "COUNTRYNAME",
           nullif(trim(to_varchar(nullif(trim("BILLING_STATE"::varchar), ''))), '') as "STATENAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where nullif(trim("BILLING_LOC"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("BILLING_LOC"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t3 as (
    -- OPUS_BJAZ_PINCODE
    select distinct nullif(trim("PINCODE"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("CITY"::varchar), ''))), '') as "CITY",
           nullif(trim(to_varchar(nullif(trim("STATUS"::varchar), ''))), '') as "POSTALCODE",
           nullif(trim(to_varchar(nullif(trim("STATE"::varchar), ''))), '') as "STATENAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t4 as (
    -- OPUS_BJAZ_PINCODE_MASTER
    select distinct nullif(trim("PINCODE"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("CITY"::varchar), ''))), '') as "CITY",
           nullif(trim(to_varchar(nullif(trim("STATE"::varchar), ''))), '') as "STATENAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t5 as (
    -- OPUS_CP_ADDRESSES
    select distinct nullif(trim("ADD_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("ADDRESS_LINE1"::varchar), ''))), '') as "ADDRESSLINE1",
           nullif(trim(to_varchar(nullif(trim("ADDRESS_LINE2"::varchar), ''))), '') as "ADDRESSLINE2",
           nullif(trim(to_varchar(nullif(trim("ADDRESS_LINE3"::varchar), ''))), '') as "ADDRESSLINE3",
           nullif(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), ''))), '') as "COUNTRYCODE",
           nullif(trim(to_varchar(nullif(trim("POSTCODE"::varchar), ''))), '') as "POSTALCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_ADDRESSES
     where nullif(trim("ADD_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("ADD_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t1."ADDRESSLINE1", st1_t5."ADDRESSLINE1") as "ADDRESSLINE1",
           coalesce(st1_t0."ADDRESSLINE2", st1_t1."ADDRESSLINE2", st1_t5."ADDRESSLINE2") as "ADDRESSLINE2",
           coalesce(st1_t0."ADDRESSLINE3", st1_t1."ADDRESSLINE3", st1_t5."ADDRESSLINE3") as "ADDRESSLINE3",
           st1_t0."BUILDINGNAME" as "BUILDINGNAME",
           coalesce(st1_t3."CITY", st1_t4."CITY") as "CITY",
           coalesce(st1_t1."COUNTRYCODE", st1_t5."COUNTRYCODE") as "COUNTRYCODE",
           coalesce(st1_t0."COUNTRYNAME", st1_t1."COUNTRYNAME") as "COUNTRYNAME",
           st1_t0."DOORNUMBER" as "DOORNUMBER",
           coalesce(st1_t3."POSTALCODE", st1_t5."POSTALCODE") as "POSTALCODE",
           coalesce(st1_t1."STATENAME", st1_t3."STATENAME", st1_t4."STATENAME") as "STATENAME",
           st1_t0."STREETNAME" as "STREETNAME",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_AZBJ_ADDRESS_EXTN' end,
               case when st1_t1."PARENT_BK" is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_PINCODE' end,
               case when st1_t4."PARENT_BK" is not null then 'OPUS_BJAZ_PINCODE_MASTER' end,
               case when st1_t5."PARENT_BK" is not null then 'OPUS_CP_ADDRESSES' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t1."LDTS", st1_t3."LDTS", st1_t4."LDTS", st1_t5."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t1 on st1_t1."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
      left join st1_t4 on st1_t4."PARENT_BK" = ak."PARENT_BK"
      left join st1_t5 on st1_t5."PARENT_BK" = ak."PARENT_BK"
),
