    select distinct case when nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), '') is not null then coalesce(nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("LOCATION"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("POST_OFFICE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("DISTRICT"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), ''), '') end as "PARENT_BK",
           nullif(trim(to_varchar(upper(nullif(trim("BUILDING"::varchar), '')))), '') as "BUILDINGNAME",
           nullif(trim(to_varchar(upper(nullif(trim("COUNTRY_CODE"::varchar), '')))), '') as "COUNTRYCODE",
           nullif(trim(to_varchar(upper(nullif(trim("HOUSE_NUMBER"::varchar), '')))), '') as "DOORNUMBER",
           nullif(trim(to_varchar(upper(nullif(trim("PIN_CODE"::varchar), '')))), '') as "POSTALCODE",
           nullif(trim(to_varchar(upper(nullif(trim("STATE"::varchar), '')))), '') as "STATENAME",
           nullif(trim(to_varchar(upper(nullif(trim("STREET"::varchar), '')))), '') as "STREETNAME",
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR
     where case when nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), '') is not null then coalesce(nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("LOCATION"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("POST_OFFICE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("DISTRICT"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (case when nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), '') is not null or nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), '') is not null then coalesce(nullif(upper(trim(to_varchar(nullif(trim("HOUSE_NUMBER"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("BUILDING"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STREET"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("LOCATION"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("POST_OFFICE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("DISTRICT"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PIN_CODE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("COUNTRY_CODE"::varchar), '')))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st2 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st2_t0."ADDRESSLINE1", st2_t1."ADDRESSLINE1", st2_t3."ADDRESSLINE1", st2_t4."ADDRESSLINE1", st2_t5."ADDRESSLINE1") as "ADDRESSLINE1",
           coalesce(st2_t3."ADDRESSLINE2", st2_t4."ADDRESSLINE2", st2_t5."ADDRESSLINE2") as "ADDRESSLINE2",
           coalesce(st2_t3."ADDRESSLINE3", st2_t4."ADDRESSLINE3", st2_t5."ADDRESSLINE3") as "ADDRESSLINE3",
           st2_t7."BUILDINGNAME" as "BUILDINGNAME",
           st2_t0."CAREOFNAME" as "CAREOFNAME",
           coalesce(st2_t3."CITY", st2_t4."CITY", st2_t5."CITY", st2_t6."CITY") as "CITY",
           st2_t7."COUNTRYCODE" as "COUNTRYCODE",
           coalesce(st2_t3."COUNTRYNAME", st2_t4."COUNTRYNAME", st2_t5."COUNTRYNAME", st2_t6."COUNTRYNAME") as "COUNTRYNAME",
           coalesce(st2_t6."DOORNUMBER", st2_t7."DOORNUMBER") as "DOORNUMBER",
           coalesce(st2_t0."POSTALCODE", st2_t3."POSTALCODE", st2_t5."POSTALCODE", st2_t6."POSTALCODE", st2_t7."POSTALCODE") as "POSTALCODE",
           coalesce(st2_t0."STATENAME", st2_t2."STATENAME", st2_t3."STATENAME", st2_t4."STATENAME", st2_t5."STATENAME", st2_t6."STATENAME", st2_t7."STATENAME") as "STATENAME",
           coalesce(st2_t6."STREETNAME", st2_t7."STREETNAME") as "STREETNAME",
           array_to_string(array_construct_compact(
               case when st2_t0."PARENT_BK" is not null then 'OPUS_BJAZ_M_KYC_DRIVING_LICENCE' end,
               case when st2_t1."PARENT_BK" is not null then 'OPUS_BJAZ_M_KYC_GSTN' end,
               case when st2_t2."PARENT_BK" is not null then 'OPUS_BJAZ_M_KYC_VOTER' end,
               case when st2_t3."PARENT_BK" is not null then 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' end,
               case when st2_t4."PARENT_BK" is not null then 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' end,
               case when st2_t5."PARENT_BK" is not null then 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' end,
               case when st2_t6."PARENT_BK" is not null then 'OPUS_BJAZ_T_EKYC' end,
               case when st2_t7."PARENT_BK" is not null then 'OPUS_BJAZ_T_KYC_OCR' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st2_t0."LDTS", st2_t1."LDTS", st2_t2."LDTS", st2_t3."LDTS", st2_t4."LDTS", st2_t5."LDTS", st2_t6."LDTS", st2_t7."LDTS") as "INC_JOB_UPDATED_AT"
      from st2_ak ak
      left join st2_t0 on st2_t0."PARENT_BK" = ak."PARENT_BK"
      left join st2_t1 on st2_t1."PARENT_BK" = ak."PARENT_BK"
      left join st2_t2 on st2_t2."PARENT_BK" = ak."PARENT_BK"
      left join st2_t3 on st2_t3."PARENT_BK" = ak."PARENT_BK"
      left join st2_t4 on st2_t4."PARENT_BK" = ak."PARENT_BK"
      left join st2_t5 on st2_t5."PARENT_BK" = ak."PARENT_BK"
      left join st2_t6 on st2_t6."PARENT_BK" = ak."PARENT_BK"
      left join st2_t7 on st2_t7."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_common_address  via stg2_common_address <- stitch_common_address
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'ADDRESSLINE1', to_varchar("ADDRESSLINE1"),
               'ADDRESSLINE2', to_varchar("ADDRESSLINE2"),
               'ADDRESSLINE3', to_varchar("ADDRESSLINE3"),
               'BUILDINGNAME', to_varchar("BUILDINGNAME"),
               'CITY', to_varchar("CITY"),
               'COUNTRYCODE', to_varchar("COUNTRYCODE"),
               'COUNTRYNAME', to_varchar("COUNTRYNAME"),
               'DOORNUMBER', to_varchar("DOORNUMBER"),
               'POSTALCODE', to_varchar("POSTALCODE"),
               'STATENAME', to_varchar("STATENAME"),
               'STREETNAME', to_varchar("STREETNAME")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. stitch stitch_kyc_common_address  via stg2_kyc_common_address <- stitch_kyc_common_address
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'ADDRESSLINE1', to_varchar("ADDRESSLINE1"),
               'ADDRESSLINE2', to_varchar("ADDRESSLINE2"),
               'ADDRESSLINE3', to_varchar("ADDRESSLINE3"),
               'BUILDINGNAME', to_varchar("BUILDINGNAME"),
               'CITY', to_varchar("CITY"),
               'COUNTRYCODE', to_varchar("COUNTRYCODE"),
               'COUNTRYNAME', to_varchar("COUNTRYNAME"),
               'DOORNUMBER', to_varchar("DOORNUMBER"),
               'POSTALCODE', to_varchar("POSTALCODE"),
               'STATENAME', to_varchar("STATENAME"),
               'STREETNAME', to_varchar("STREETNAME")
           ) as obj
      from st2
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_COMMON_ADDRESS' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 102. OPUS — SAT_COMMON_ADMIN_GEOGRAPHY   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 1 column(s) compared. 1 RAW branch(es): stitch
-- stitch_shared__common_admin_geography_common_geo.
-- stitch_shared__common_admin_geography_common_geo reproduced from 2 RAW tables with no
-- watermark window; every row combination per key is kept because the stitch keeps one
-- of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.LOCATION_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'PINCODE', to_varchar(s."PINCODE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADMIN_GEOGRAPHY s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_shared__common_admin_geography_common_geo: every key of every contributing table (no watermark window)
    select nullif(trim("PINCODE"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PINCODE"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_BJAZ_PINCODE
    select distinct nullif(trim("PINCODE"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("PINCODE"::varchar), ''))), '') as "PINCODE",
           nullif(trim(to_varchar(nullif(trim("ZONE1"::varchar), ''))), '') as "REGIONCODE",
           nullif(trim(to_varchar(nullif(trim("STATE"::varchar), ''))), '') as "REGIONNAME",
           nullif(trim(to_varchar(nullif(trim("ZONE2"::varchar), ''))), '') as "SUBZONECODE",
           nullif(trim(to_varchar(nullif(trim("ZONE"::varchar), ''))), '') as "ZONECODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t1 as (
    -- OPUS_BJAZ_PINCODE_MASTER
    select distinct nullif(trim("PINCODE"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("PINCODE"::varchar), ''))), '') as "PINCODE",
           nullif(trim(to_varchar(nullif(trim("ZONE1"::varchar), ''))), '') as "REGIONCODE",
           nullif(trim(to_varchar(nullif(trim("STATE"::varchar), ''))), '') as "REGIONNAME",
           nullif(trim(to_varchar(nullif(trim("ZONE2"::varchar), ''))), '') as "SUBZONECODE",
           nullif(trim(to_varchar(nullif(trim("ZONE_PIN"::varchar), ''))), '') as "ZONECODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where nullif(trim("PINCODE"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || (nullif(trim("PINCODE"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t0."PINCODE", st1_t1."PINCODE") as "PINCODE",
           coalesce(st1_t0."REGIONCODE", st1_t1."REGIONCODE") as "REGIONCODE",
           coalesce(st1_t0."REGIONNAME", st1_t1."REGIONNAME") as "REGIONNAME",
           coalesce(st1_t0."SUBZONECODE", st1_t1."SUBZONECODE") as "SUBZONECODE",
           coalesce(st1_t0."ZONECODE", st1_t1."ZONECODE") as "ZONECODE",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_BJAZ_PINCODE' end,
               case when st1_t1."PARENT_BK" is not null then 'OPUS_BJAZ_PINCODE_MASTER' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t1."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t1 on st1_t1."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_shared__common_admin_geography_common_geo  via stg2_shared__common_admin_geography_common_geo <- stitch_shared__common_admin_geography_common_geo
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_LOCATION|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'PINCODE', to_varchar("PINCODE")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_COMMON_ADMIN_GEOGRAPHY' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 103. OPUS — SAT_COMMON_CLASSIFICATION   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 2 column(s) compared. 1 RAW branch(es): stitch
-- stitch_common_classification. stitch_common_classification reproduced from 3 RAW
-- tables with no watermark window; every row combination per key is kept because the
-- stitch keeps one of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'PRIORITYCODE', to_varchar(s."PRIORITYCODE"),
               'SEGMENTCODE', to_varchar(s."SEGMENTCODE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CLASSIFICATION s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_common_classification: every key of every contributing table (no watermark window)
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("INTERMEDIARY_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_INTERMEDIARY
     where nullif(trim("INTERMEDIARY_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("INTERMEDIARY_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_AZBJ_PARTNER_EXTN
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("VIP_CUST"::varchar), ''))), '') as "PRIORITYCODE",
           nullif(trim(to_varchar(nullif(trim("UCIC_FLAG"::varchar), ''))), '') as "SEGMENTCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t2 as (
    -- OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("VIP_FLG"::varchar), ''))), '') as "PRIORITYCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t3 as (
    -- OPUS_BJAZ_INTERMEDIARY
    select distinct nullif(trim("INTERMEDIARY_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("FLAGGING"::varchar), ''))), '') as "SEGMENTCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_INTERMEDIARY
     where nullif(trim("INTERMEDIARY_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("INTERMEDIARY_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t0."PRIORITYCODE", st1_t2."PRIORITYCODE") as "PRIORITYCODE",
           coalesce(st1_t0."SEGMENTCODE", st1_t3."SEGMENTCODE") as "SEGMENTCODE",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when st1_t2."PARENT_BK" is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_INTERMEDIARY' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t2."LDTS", st1_t3."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t2 on st1_t2."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_common_classification  via stg2_common_classification <- stitch_common_classification
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'PRIORITYCODE', to_varchar("PRIORITYCODE"),
               'SEGMENTCODE', to_varchar("SEGMENTCODE")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_COMMON_CLASSIFICATION' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
