      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_HM_MEMBER_DTLS  via stg2_sat_bjaz_hm_member_dtls__party_banking <- stg_partner__bjaz_hm_member_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HM_MEMBER_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'ACCOUNTNUMBERMASKED', to_varchar(nullif(trim("BANK_AC_NO"::varchar), '')),
               'BANKCODE', to_varchar(null),
               'BANKNAME', to_varchar(nullif(trim("BANK_NAME"::varchar), '')),
               'IFSCCODE', to_varchar(null),
               'MICRCODE', to_varchar(nullif(trim("MICR_CODE"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_BANKING' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 119. OPUS — SAT_PARTY_CLAIM_HISTORY   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 2 column(s) compared. 1 RAW branch(es): stitch
-- stitch_party_claim_history. stitch_party_claim_history reproduced from 6 RAW tables
-- with no watermark window; every row combination per key is kept because the stitch
-- keeps one of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'TOTALCLAIMAMOUNT', to_varchar(s."TOTALCLAIMAMOUNT"),
               'TOTALCLAIMCOUNT', to_varchar(s."TOTALCLAIMCOUNT")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CLAIM_HISTORY s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_party_claim_history: every key of every contributing table (no watermark window)
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("CLAIM_RECEIVED"::number))), '') as "TOTALCLAIMCOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t1 as (
    -- OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("CLAIM_DTLS"::varchar), ''))), '') as "TOTALCLAIMCOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t2 as (
    -- OPUS_BJAZ_HC_PART_EXTN
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("AMOUNT_CLAIMED"::number))), '') as "TOTALCLAIMAMOUNT",
           nullif(trim(to_varchar(nullif(trim("CLAIM_HISTORY"::varchar), ''))), '') as "TOTALCLAIMCOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t3 as (
    -- OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("CLAIM_COUNT"::number))), '') as "TOTALCLAIMCOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t4 as (
    -- OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("AMOUNT_CLAIMED"::number))), '') as "TOTALCLAIMAMOUNT",
           nullif(trim(to_varchar(nullif(trim("CLAIM_HISTORY"::varchar), ''))), '') as "TOTALCLAIMCOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t5 as (
    -- OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("CLAIM_DTLS"::varchar), ''))), '') as "TOTALCLAIMCOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t2."TOTALCLAIMAMOUNT", st1_t4."TOTALCLAIMAMOUNT") as "TOTALCLAIMAMOUNT",
           coalesce(st1_t0."TOTALCLAIMCOUNT", st1_t1."TOTALCLAIMCOUNT", st1_t2."TOTALCLAIMCOUNT", st1_t3."TOTALCLAIMCOUNT", st1_t4."TOTALCLAIMCOUNT", st1_t5."TOTALCLAIMCOUNT") as "TOTALCLAIMCOUNT",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when st1_t1."PARENT_BK" is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when st1_t2."PARENT_BK" is not null then 'OPUS_BJAZ_HC_PART_EXTN' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when st1_t4."PARENT_BK" is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when st1_t5."PARENT_BK" is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t1."LDTS", st1_t2."LDTS", st1_t3."LDTS", st1_t4."LDTS", st1_t5."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t1 on st1_t1."PARENT_BK" = ak."PARENT_BK"
      left join st1_t2 on st1_t2."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
      left join st1_t4 on st1_t4."PARENT_BK" = ak."PARENT_BK"
      left join st1_t5 on st1_t5."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_party_claim_history  via stg2_party_claim_history <- stitch_party_claim_history
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'TOTALCLAIMAMOUNT', to_varchar("TOTALCLAIMAMOUNT"),
               'TOTALCLAIMCOUNT', to_varchar("TOTALCLAIMCOUNT")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_CLAIM_HISTORY' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 120. OPUS — SAT_PARTY_CONTACT_ADDRESS_LINK   [Implemented]
-- Mode -- multi-active: the current vault set and the latest source set of each (hash
-- key, record source) must contain the same rows. 2 column(s) compared. 3 RAW
-- branch(es): BJAZ_CP_ADDRESS_LINK, BJAZ_T_CKYC_PERSONAL_DTLS.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_LOCATION_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ADDRESS_USAGE_TYPE', to_varchar(s."ADDRESS_USAGE_TYPE"),
               'PRIMARY_ADDRESS_INDICATOR', to_varchar(s."PRIMARY_ADDRESS_INDICATOR")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_CONTACT_ADDRESS_LINK s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BJAZ_CP_ADDRESS_LINK  via stg2_pcal_bjaz_cp_address_link <- stg_partner__bjaz_cp_address_link
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('LNK_PARTY_LOCATION|' || nullif(trim("PART_ID"::varchar), '') || '|' || nullif(trim("ADD_ID"::varchar), '')) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CP_ADDRESS_LINK' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'ADDRESS_USAGE_TYPE', to_varchar(to_varchar(("ADD_TYPE"::number))),
               'PRIMARY_ADDRESS_INDICATOR', to_varchar(nullif(trim("PRIMARY_YN"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CP_ADDRESS_LINK
     where to_varchar(("ADD_TYPE"::number)) is not null
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_contact_address_link__correspondence <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('LNK_PARTY_LOCATION|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_LINE1"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_LINE2"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_LINE3"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_CITY"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_DIST"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_PIN"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("CORRES_COUNTRY"::varchar), '')))), ''), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'ADDRESS_USAGE_TYPE', to_varchar('CORRESPONDENCE'),
               'PRIMARY_ADDRESS_INDICATOR', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
     where 'CORRESPONDENCE' is not null
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_contact_address_link__permanent <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('LNK_PARTY_LOCATION|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_LINE1"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_LINE2"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_LINE3"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_CITY"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_DIST"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_STATE"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_PIN"::varchar), '')))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar(nullif(trim("PERM_COUNTRY"::varchar), '')))), ''), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'ADDRESS_USAGE_TYPE', to_varchar('PERMANENT'),
               'PRIMARY_ADDRESS_INDICATOR', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
     where 'PERMANENT' is not null
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
src_not_in_vault as (
    -- multi-active: every source row of the latest source set must be in the vault's current set
    select u.hkey, u.rs, count(*) as n
      from (select * from src_n qualify rank() over (partition by hkey, rs_key order by ldts desc) = 1) s
      join sample_units u on u.hkey = s.hkey and u.rs_key = s.rs_key
     where not exists (select 1 from pairs p where p.src_row_id = s.src_row_id and p.hkey = u.hkey
                                               and p.rs = u.rs and p.n_diff = 0)
     group by u.hkey, u.rs
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           any_value(coalesce(x.n, 0)) as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and any_value(coalesce(x.n, 0)) = 0 then 'MATCH'
                when boolean_and_agg(m.value_match) and any_value(coalesce(x.n, 0)) = 0 then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
      left join src_not_in_vault x on x.hkey = m.hkey and x.rs = m.rs
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_CONTACT_ADDRESS_LINK' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



