    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_CLM_SUPP_EXTN  via stg2_sat_bjaz_clm_supp_extn__party_group_census <- stg_partner__bjaz_clm_supp_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CLM_SUPP_EXTN' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'ACTIVEINDICATOR', to_varchar(null),
               'DESIGNATIONBAND', to_varchar(null),
               'EMPLOYEEID', to_varchar(nullif(trim("EMPCODE"::varchar), '')),
               'LOCATIONREFERENCE', to_varchar(null),
               'MEMBERREFERENCE', to_varchar(null)
           ) as obj
