-- 124. OPUS — SAT_PARTY_HEALTH_PROFILE   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 5 column(s) compared. 3 RAW branch(es): stitch
-- stitch_party_health_profile, BJAZ_M_KYC_DRIVING_LICENCE, BJAZ_T_CKYC_PERSONAL_DTLS.
-- stitch_party_health_profile reproduced from 4 RAW tables with no watermark window;
-- every row combination per key is kept because the stitch keeps one of them
-- arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, iff(s.RECORD_SOURCE in ('OPUS_BJAZ_M_KYC_DRIVING_LICENCE', 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS'), s.RECORD_SOURCE, 'STITCH') as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'BODYMASSINDEX', to_varchar(s."BODYMASSINDEX"),
               'HEIGHT', to_varchar(s."HEIGHT"),
               'MATERNITYSTATUS', to_varchar(s."MATERNITYSTATUS"),
               'SMOKERINDICATOR', to_varchar(s."SMOKERINDICATOR"),
               'WEIGHT', to_varchar(s."WEIGHT")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_HEALTH_PROFILE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_party_health_profile: every key of every contributing table (no watermark window)
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("HEIGHT_CM"::number))), '') as "HEIGHT",
           nullif(trim(to_varchar(nullif(trim("PREGNANT_YN"::varchar), ''))), '') as "MATERNITYSTATUS",
           nullif(trim(to_varchar(nullif(trim("SMOKER_YN"::varchar), ''))), '') as "SMOKERINDICATOR",
           nullif(trim(to_varchar(("WEIGHT_KG"::number))), '') as "WEIGHT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t1 as (
    -- OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("OBESITY_FLAG"::varchar), ''))), '') as "BODYMASSINDEX",
           nullif(trim(to_varchar(nullif(trim("HEIGHT_FLAG"::varchar), ''))), '') as "HEIGHT",
           nullif(trim(to_varchar(nullif(trim("SMOKER_FLAG"::varchar), ''))), '') as "SMOKERINDICATOR",
           nullif(trim(to_varchar(nullif(trim("WEIGHT_FLAG"::varchar), ''))), '') as "WEIGHT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t2 as (
    -- OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("SMOKER_YN"::varchar), ''))), '') as "SMOKERINDICATOR",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t3 as (
    -- OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("OBESITY"::varchar), ''))), '') as "BODYMASSINDEX",
           nullif(trim(to_varchar(nullif(trim("WEIGHT"::varchar), ''))), '') as "WEIGHT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t1."BODYMASSINDEX", st1_t3."BODYMASSINDEX") as "BODYMASSINDEX",
           coalesce(st1_t0."HEIGHT", st1_t1."HEIGHT") as "HEIGHT",
           st1_t0."MATERNITYSTATUS" as "MATERNITYSTATUS",
           coalesce(st1_t0."SMOKERINDICATOR", st1_t1."SMOKERINDICATOR", st1_t2."SMOKERINDICATOR") as "SMOKERINDICATOR",
           coalesce(st1_t0."WEIGHT", st1_t1."WEIGHT", st1_t3."WEIGHT") as "WEIGHT",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when st1_t1."PARENT_BK" is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when st1_t2."PARENT_BK" is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t1."LDTS", st1_t2."LDTS", st1_t3."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t1 on st1_t1."PARENT_BK" = ak."PARENT_BK"
      left join st1_t2 on st1_t2."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_party_health_profile  via stg2_party_health_profile <- stitch_party_health_profile
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'BODYMASSINDEX', to_varchar("BODYMASSINDEX"),
               'HEIGHT', to_varchar("HEIGHT"),
               'MATERNITYSTATUS', to_varchar("MATERNITYSTATUS"),
               'SMOKERINDICATOR', to_varchar("SMOKERINDICATOR"),
               'WEIGHT', to_varchar("WEIGHT")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_M_KYC_DRIVING_LICENCE  via stg2_sat_bjaz_m_kyc_driving_licence__party_health_profile <- stg_partner__bjaz_m_kyc_driving_licence
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('LICENCE:' || upper(trim(coalesce(nullif(trim("LICENCE_NUMBER"::varchar), ''),''))), 'LICENCE:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_M_KYC_DRIVING_LICENCE' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'BODYMASSINDEX', to_varchar(null),
               'HEIGHT', to_varchar(null),
               'MATERNITYSTATUS', to_varchar(null),
               'SMOKERINDICATOR', to_varchar(null),
               'WEIGHT', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_health_profile <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'BODYMASSINDEX', to_varchar(null),
               'HEIGHT', to_varchar(null),
               'MATERNITYSTATUS', to_varchar(null),
               'SMOKERINDICATOR', to_varchar(null),
               'WEIGHT', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_HEALTH_PROFILE' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 125. OPUS — SAT_PARTY_IDENTIFICATION   [Implemented]
-- Mode -- sat_multi_source OBJECT branch: one row per hash key; object columns hold one
-- value per source table, plain columns the MAX across source rows -- reproduced from
-- RAW the same way. 13 column(s) compared. 19 RAW branch(es): AZBJ_PARTNER_EXTN,
-- BJAZ_CLM_SUPP_EXTN, BJAZ_CTNGY_FF_DTLS_EXTN, BJAZ_CTNGY_PA_MEM_DTLS,
-- BJAZ_EC_MEM_DTLS_EXTN, BJAZ_HCF_MEMBER_DTLS, BJAZ_HLT_ENSURE_MEM_DTLS,
-- BJAZ_HM_HOSPITAL_MASTER, BJAZ_INTERMEDIARY, BJAZ_STARPKG_FF_DTLS, CP_PARTNERS,
-- BJAZ_M_KYC_DRIVING_LICENCE, BJAZ_M_KYC_GSTN, BJAZ_M_KYC_PAN, BJAZ_M_KYC_PASSPORT,
-- BJAZ_M_KYC_VOTER, BJAZ_T_CKYC_OTP, BJAZ_T_KYC_INCOMING, BJAZ_T_KYC_NAME_MATCH. Not
-- mapped by this project (always NULL): CKYCNUMBER.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'AADHAARNUMBER', to_varchar(s."AADHAARNUMBER"),
               'AGEPROOFTYPE', to_varchar(s."AGEPROOFTYPE"),
               'EIANUMBER', to_varchar(s."EIANUMBER"),
               'GSTIN', to_varchar(s."GSTIN"),
               'GSTREGISTRATIONSTATUS', to_varchar(s."GSTREGISTRATIONSTATUS"),
               'GSTTAXPAYERTYPE', to_varchar(s."GSTTAXPAYERTYPE"),
               'IDENTIFICATIONNUMBER', to_varchar(s."IDENTIFICATIONNUMBER"),
               'PANNUMBER', to_varchar(s."PANNUMBER"),
               'PASSPORTNUMBER', to_varchar(s."PASSPORTNUMBER"),
               'TANNUMBER', to_varchar(s."TANNUMBER"),
               'VATREGISTRATIONNUMBER', to_varchar(s."VATREGISTRATIONNUMBER"),
               'VOTERIDNUMBER', to_varchar(s."VOTERIDNUMBER"),
               'CKYCNUMBER', to_varchar(s."CKYCNUMBER")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src_rows as (
    -- 1. AZBJ_PARTNER_EXTN  via stg2_sat_azbj_partner_extn__party_identification <- stg_partner__azbj_partner_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_AZBJ_PARTNER_EXTN' as rs,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           to_varchar(null) as "AADHAARNUMBER",
           to_varchar(null) as "AGEPROOFTYPE",
           to_varchar(nullif(trim("EIA_NO"::varchar), '')) as "EIANUMBER",
           to_varchar(null) as "GSTIN",
           to_varchar(null) as "GSTREGISTRATIONSTATUS",
           to_varchar(null) as "GSTTAXPAYERTYPE",
           to_varchar(nullif(trim("UNIQUE_ID"::varchar), '')) as "IDENTIFICATIONNUMBER",
           to_varchar(null) as "PANNUMBER",
           to_varchar(null) as "PASSPORTNUMBER",
           to_varchar(null) as "TANNUMBER",
           to_varchar(null) as "VATREGISTRATIONNUMBER",
           to_varchar(null) as "VOTERIDNUMBER",
           to_varchar(null) as "CKYCNUMBER"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_CLM_SUPP_EXTN  via stg2_sat_bjaz_clm_supp_extn__party_identification <- stg_partner__bjaz_clm_supp_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CLM_SUPP_EXTN' as rs,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           to_varchar(null) as "AADHAARNUMBER",
           to_varchar(null) as "AGEPROOFTYPE",
           to_varchar(null) as "EIANUMBER",
           to_varchar(null) as "GSTIN",
           to_varchar(null) as "GSTREGISTRATIONSTATUS",
           to_varchar(nullif(trim("TAXPAYER_TYPE"::varchar), '')) as "GSTTAXPAYERTYPE",
           to_varchar(null) as "IDENTIFICATIONNUMBER",
           to_varchar(nullif(trim("PAN_NO"::varchar), '')) as "PANNUMBER",
           to_varchar(null) as "PASSPORTNUMBER",
           to_varchar(nullif(trim("TAN_NUMBER"::varchar), '')) as "TANNUMBER",
           to_varchar(null) as "VATREGISTRATIONNUMBER",
           to_varchar(null) as "VOTERIDNUMBER",
           to_varchar(null) as "CKYCNUMBER"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_CTNGY_FF_DTLS_EXTN  via stg2_sat_bjaz_ctngy_ff_dtls_extn__party_identification <- stg_partner__bjaz_ctngy_ff_dtls_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CTNGY_FF_DTLS_EXTN' as rs,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           to_varchar(null) as "AADHAARNUMBER",
           to_varchar(null) as "AGEPROOFTYPE",
           to_varchar(null) as "EIANUMBER",
           to_varchar(null) as "GSTIN",
           to_varchar(null) as "GSTREGISTRATIONSTATUS",
           to_varchar(null) as "GSTTAXPAYERTYPE",
           to_varchar(null) as "IDENTIFICATIONNUMBER",
           to_varchar(null) as "PANNUMBER",
           to_varchar(nullif(trim("PASSPORTNO"::varchar), '')) as "PASSPORTNUMBER",
           to_varchar(null) as "TANNUMBER",
           to_varchar(null) as "VATREGISTRATIONNUMBER",
           to_varchar(null) as "VOTERIDNUMBER",
           to_varchar(null) as "CKYCNUMBER"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_FF_DTLS_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_CTNGY_PA_MEM_DTLS  via stg2_sat_bjaz_ctngy_pa_mem_dtls__party_identification <- stg_partner__bjaz_ctngy_pa_mem_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' as rs,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           to_varchar(nullif(trim("AADHAR_CARD_NO"::varchar), '')) as "AADHAARNUMBER",
           to_varchar(null) as "AGEPROOFTYPE",
           to_varchar(nullif(trim("EIA_NO"::varchar), '')) as "EIANUMBER",
           to_varchar(null) as "GSTIN",
           to_varchar(null) as "GSTREGISTRATIONSTATUS",
           to_varchar(null) as "GSTTAXPAYERTYPE",
           to_varchar(("MEMBER_REF_NUMBER"::number)) as "IDENTIFICATIONNUMBER",
           to_varchar(nullif(trim("PAN_CARD_NO"::varchar), '')) as "PANNUMBER",
           to_varchar(nullif(trim("PASSPORT_NUMBER"::varchar), '')) as "PASSPORTNUMBER",
           to_varchar(null) as "TANNUMBER",
           to_varchar(null) as "VATREGISTRATIONNUMBER",
           to_varchar(null) as "VOTERIDNUMBER",
           to_varchar(null) as "CKYCNUMBER"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_EC_MEM_DTLS_EXTN  via stg2_sat_bjaz_ec_mem_dtls_extn__party_identification <- stg_partner__bjaz_ec_mem_dtls_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_EC_MEM_DTLS_EXTN' as rs,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           to_varchar(null) as "AADHAARNUMBER",
           to_varchar(nullif(trim("AGE_PROOF"::varchar), '')) as "AGEPROOFTYPE",
           to_varchar(null) as "EIANUMBER",
           to_varchar(null) as "GSTIN",
           to_varchar(null) as "GSTREGISTRATIONSTATUS",
           to_varchar(null) as "GSTTAXPAYERTYPE",
           to_varchar(null) as "IDENTIFICATIONNUMBER",
           to_varchar(null) as "PANNUMBER",
           to_varchar(null) as "PASSPORTNUMBER",
           to_varchar(null) as "TANNUMBER",
           to_varchar(null) as "VATREGISTRATIONNUMBER",
