src_tbl as (
    -- sat_multi_source OBJECT branch: one value per (key, source table), then one row per key
    select hkey, regexp_replace(rs, '^OPUS_', '') as source_table, max(ldts) as ldts,
           max("AADHAARNUMBER") as "AADHAARNUMBER",
           max("AGEPROOFTYPE") as "AGEPROOFTYPE",
           max("EIANUMBER") as "EIANUMBER",
           max("GSTIN") as "GSTIN",
           max("GSTREGISTRATIONSTATUS") as "GSTREGISTRATIONSTATUS",
           max("GSTTAXPAYERTYPE") as "GSTTAXPAYERTYPE",
           max("IDENTIFICATIONNUMBER") as "IDENTIFICATIONNUMBER",
           max("PANNUMBER") as "PANNUMBER",
           max("PASSPORTNUMBER") as "PASSPORTNUMBER",
           max("TANNUMBER") as "TANNUMBER",
           max("VATREGISTRATIONNUMBER") as "VATREGISTRATIONNUMBER",
           max("VOTERIDNUMBER") as "VOTERIDNUMBER",
           max("CKYCNUMBER") as "CKYCNUMBER"
      from src_rows
     group by hkey, source_table
),
src as (
    select hkey, 'OPUS' as rs_key, max(ldts) as ldts,
           object_construct_keep_null(
               'AADHAARNUMBER', to_varchar(object_agg(source_table, to_variant("AADHAARNUMBER"))),
               'GSTIN', to_varchar(object_agg(source_table, to_variant("GSTIN"))),
               'PANNUMBER', to_varchar(object_agg(source_table, to_variant("PANNUMBER"))),
               'PASSPORTNUMBER', to_varchar(object_agg(source_table, to_variant("PASSPORTNUMBER"))),
               'VOTERIDNUMBER', to_varchar(object_agg(source_table, to_variant("VOTERIDNUMBER"))),
               'CKYCNUMBER', to_varchar(object_agg(source_table, to_variant("CKYCNUMBER"))),
               'AGEPROOFTYPE', max("AGEPROOFTYPE"),
               'EIANUMBER', max("EIANUMBER"),
               'GSTREGISTRATIONSTATUS', max("GSTREGISTRATIONSTATUS"),
               'GSTTAXPAYERTYPE', max("GSTTAXPAYERTYPE"),
               'IDENTIFICATIONNUMBER', max("IDENTIFICATIONNUMBER"),
               'TANNUMBER', max("TANNUMBER"),
               'VATREGISTRATIONNUMBER', max("VATREGISTRATIONNUMBER")
           ) as obj
      from src_tbl
     group by hkey
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_IDENTIFICATION' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 126. OPUS — SAT_PARTY_IDENTITY   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 17 column(s) compared. 9 RAW branch(es): stitch
-- stitch_party_identity, BJAZ_T_CKYC_PERSONAL_DTLS, BJAZ_T_CKYC_REL_PERSION_DTLS,
-- BJAZ_T_CKYC_SEARCH, BJAZ_T_EKYC, BJAZ_T_KYC_AUTH, BJAZ_T_KYC_DETAILS,
-- BJAZ_T_KYC_INCOMING, BJAZ_T_KYC_OCR. stitch_party_identity reproduced from 19 RAW
-- tables with no watermark window; every row combination per key is kept because the
-- stitch keeps one of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, iff(s.RECORD_SOURCE in ('OPUS_BJAZ_T_CKYC_PERSONAL_DTLS', 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS', 'OPUS_BJAZ_T_CKYC_SEARCH', 'OPUS_BJAZ_T_EKYC', 'OPUS_BJAZ_T_KYC_AUTH', 'OPUS_BJAZ_T_KYC_DETAILS', 'OPUS_BJAZ_T_KYC_INCOMING', 'OPUS_BJAZ_T_KYC_OCR'), s.RECORD_SOURCE, 'STITCH') as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'AGE', to_varchar(s."AGE"),
               'DATEOFBIRTH', to_varchar(s."DATEOFBIRTH"),
               'DATEOFDEATH', to_varchar(s."DATEOFDEATH"),
               'FIRSTNAME', to_varchar(s."FIRSTNAME"),
               'GENDERCODE', to_varchar(s."GENDERCODE"),
               'LASTNAME', to_varchar(s."LASTNAME"),
               'MIDDLENAME', to_varchar(s."MIDDLENAME"),
               'NAMESUFFIX', to_varchar(s."NAMESUFFIX"),
               'NATIONALITY', to_varchar(s."NATIONALITY"),
               'PARTYDISPLAYNAME', to_varchar(s."PARTYDISPLAYNAME"),
               'PARTYFULLNAME', to_varchar(s."PARTYFULLNAME"),
               'PARTYLEGALNAME', to_varchar(s."PARTYLEGALNAME"),
               'PARTYSHORTNAME', to_varchar(s."PARTYSHORTNAME"),
               'PARTYSTATUS', to_varchar(s."PARTYSTATUS"),
               'PARTYTYPECODE', to_varchar(s."PARTYTYPECODE"),
               'PLACEOFBIRTH', to_varchar(s."PLACEOFBIRTH"),
               'SALUTATION', to_varchar(s."SALUTATION")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
