),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t6."AGE", st1_t7."AGE", st1_t8."AGE", st1_t9."AGE", st1_t10."AGE", st1_t11."AGE", st1_t13."AGE", st1_t16."AGE", st1_t17."AGE", st1_t18."AGE", st1_t19."AGE") as "AGE",
           coalesce(st1_t5."DATEOFBIRTH", st1_t6."DATEOFBIRTH", st1_t7."DATEOFBIRTH", st1_t8."DATEOFBIRTH", st1_t9."DATEOFBIRTH", st1_t10."DATEOFBIRTH", st1_t11."DATEOFBIRTH", st1_t13."DATEOFBIRTH", st1_t16."DATEOFBIRTH", st1_t17."DATEOFBIRTH", st1_t18."DATEOFBIRTH", st1_t19."DATEOFBIRTH", st1_t20."DATEOFBIRTH") as "DATEOFBIRTH",
           st1_t20."DATEOFDEATH" as "DATEOFDEATH",
           coalesce(st1_t3."FIRSTNAME", st1_t20."FIRSTNAME") as "FIRSTNAME",
           coalesce(st1_t5."GENDERCODE", st1_t6."GENDERCODE", st1_t7."GENDERCODE", st1_t8."GENDERCODE", st1_t9."GENDERCODE", st1_t10."GENDERCODE", st1_t11."GENDERCODE", st1_t13."GENDERCODE", st1_t17."GENDERCODE", st1_t18."GENDERCODE", st1_t19."GENDERCODE", st1_t20."GENDERCODE") as "GENDERCODE",
           coalesce(st1_t3."LASTNAME", st1_t7."LASTNAME", st1_t20."LASTNAME") as "LASTNAME",
           coalesce(st1_t3."MIDDLENAME", st1_t7."MIDDLENAME", st1_t20."MIDDLENAME") as "MIDDLENAME",
           st1_t20."NAMESUFFIX" as "NAMESUFFIX",
           st1_t20."NATIONALITY" as "NATIONALITY",
           st1_t12."PARTYDISPLAYNAME" as "PARTYDISPLAYNAME",
           coalesce(st1_t1."PARTYFULLNAME", st1_t3."PARTYFULLNAME", st1_t5."PARTYFULLNAME", st1_t6."PARTYFULLNAME", st1_t7."PARTYFULLNAME", st1_t8."PARTYFULLNAME", st1_t9."PARTYFULLNAME", st1_t10."PARTYFULLNAME", st1_t11."PARTYFULLNAME", st1_t12."PARTYFULLNAME", st1_t13."PARTYFULLNAME", st1_t14."PARTYFULLNAME", st1_t16."PARTYFULLNAME", st1_t17."PARTYFULLNAME", st1_t18."PARTYFULLNAME", st1_t19."PARTYFULLNAME", st1_t20."PARTYFULLNAME", st1_t21."PARTYFULLNAME") as "PARTYFULLNAME",
           coalesce(st1_t3."PARTYLEGALNAME", st1_t9."PARTYLEGALNAME", st1_t17."PARTYLEGALNAME", st1_t18."PARTYLEGALNAME", st1_t20."PARTYLEGALNAME") as "PARTYLEGALNAME",
           st1_t20."PARTYSHORTNAME" as "PARTYSHORTNAME",
           coalesce(st1_t0."PARTYSTATUS", st1_t8."PARTYSTATUS", st1_t10."PARTYSTATUS", st1_t17."PARTYSTATUS") as "PARTYSTATUS",
           st1_t20."PARTYTYPECODE" as "PARTYTYPECODE",
           st1_t0."PLACEOFBIRTH" as "PLACEOFBIRTH",
           st1_t20."SALUTATION" as "SALUTATION",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when st1_t1."PARENT_BK" is not null then 'OPUS_BA_HCP_DT_MEM' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when st1_t5."PARENT_BK" is not null then 'OPUS_BJAZ_CTNGY_FF_DTLS_EXTN' end,
               case when st1_t6."PARENT_BK" is not null then 'OPUS_BJAZ_CTNGY_GC_MEM_DATA' end,
               case when st1_t7."PARENT_BK" is not null then 'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' end,
               case when st1_t8."PARENT_BK" is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when st1_t9."PARENT_BK" is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when st1_t10."PARENT_BK" is not null then 'OPUS_BJAZ_HC_PART_EXTN' end,
               case when st1_t11."PARENT_BK" is not null then 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' end,
               case when st1_t12."PARENT_BK" is not null then 'OPUS_BJAZ_HM_HOSPITAL_MASTER' end,
               case when st1_t13."PARENT_BK" is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when st1_t14."PARENT_BK" is not null then 'OPUS_BJAZ_INTERMEDIARY' end,
               case when st1_t16."PARENT_BK" is not null then 'OPUS_BJAZ_PA_DETL_EXTN' end,
               case when st1_t17."PARENT_BK" is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when st1_t18."PARENT_BK" is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end,
               case when st1_t19."PARENT_BK" is not null then 'OPUS_BJAZ_STARPKG_FF_DTLS' end,
               case when st1_t20."PARENT_BK" is not null then 'OPUS_CP_PARTNERS' end,
               case when st1_t21."PARENT_BK" is not null then 'OPUS_OCP_INTERESTED_PARTIES' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t1."LDTS", st1_t3."LDTS", st1_t5."LDTS", st1_t6."LDTS", st1_t7."LDTS", st1_t8."LDTS", st1_t9."LDTS", st1_t10."LDTS", st1_t11."LDTS", st1_t12."LDTS", st1_t13."LDTS", st1_t14."LDTS", st1_t16."LDTS", st1_t17."LDTS", st1_t18."LDTS", st1_t19."LDTS", st1_t20."LDTS", st1_t21."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t1 on st1_t1."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
      left join st1_t5 on st1_t5."PARENT_BK" = ak."PARENT_BK"
      left join st1_t6 on st1_t6."PARENT_BK" = ak."PARENT_BK"
      left join st1_t7 on st1_t7."PARENT_BK" = ak."PARENT_BK"
      left join st1_t8 on st1_t8."PARENT_BK" = ak."PARENT_BK"
      left join st1_t9 on st1_t9."PARENT_BK" = ak."PARENT_BK"
      left join st1_t10 on st1_t10."PARENT_BK" = ak."PARENT_BK"
      left join st1_t11 on st1_t11."PARENT_BK" = ak."PARENT_BK"
      left join st1_t12 on st1_t12."PARENT_BK" = ak."PARENT_BK"
      left join st1_t13 on st1_t13."PARENT_BK" = ak."PARENT_BK"
      left join st1_t14 on st1_t14."PARENT_BK" = ak."PARENT_BK"
      left join st1_t16 on st1_t16."PARENT_BK" = ak."PARENT_BK"
      left join st1_t17 on st1_t17."PARENT_BK" = ak."PARENT_BK"
      left join st1_t18 on st1_t18."PARENT_BK" = ak."PARENT_BK"
      left join st1_t19 on st1_t19."PARENT_BK" = ak."PARENT_BK"
      left join st1_t20 on st1_t20."PARENT_BK" = ak."PARENT_BK"
      left join st1_t21 on st1_t21."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_party_identity  via stg2_party_identity <- stitch_party_identity
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'AGE', to_varchar("AGE"),
               'DATEOFBIRTH', to_varchar("DATEOFBIRTH"),
               'DATEOFDEATH', to_varchar("DATEOFDEATH"),
               'FIRSTNAME', to_varchar("FIRSTNAME"),
               'GENDERCODE', to_varchar("GENDERCODE"),
               'LASTNAME', to_varchar("LASTNAME"),
               'MIDDLENAME', to_varchar("MIDDLENAME"),
               'NAMESUFFIX', to_varchar("NAMESUFFIX"),
               'NATIONALITY', to_varchar("NATIONALITY"),
               'PARTYDISPLAYNAME', to_varchar("PARTYDISPLAYNAME"),
               'PARTYFULLNAME', to_varchar("PARTYFULLNAME"),
               'PARTYLEGALNAME', to_varchar("PARTYLEGALNAME"),
               'PARTYSHORTNAME', to_varchar("PARTYSHORTNAME"),
               'PARTYSTATUS', to_varchar("PARTYSTATUS"),
               'PARTYTYPECODE', to_varchar("PARTYTYPECODE"),
               'PLACEOFBIRTH', to_varchar("PLACEOFBIRTH"),
               'SALUTATION', to_varchar("SALUTATION")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_identity <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'AGE', to_varchar(null),
               'DATEOFBIRTH', to_varchar(nullif(trim("DOB"::varchar), '')),
               'DATEOFDEATH', to_varchar(null),
               'FIRSTNAME', to_varchar(nullif(trim("FNAME"::varchar), '')),
               'GENDERCODE', to_varchar(nullif(trim("GENDER"::varchar), '')),
               'LASTNAME', to_varchar(nullif(trim("LNAME"::varchar), '')),
               'MIDDLENAME', to_varchar(nullif(trim("MNAME"::varchar), '')),
               'NAMESUFFIX', to_varchar(null),
               'NATIONALITY', to_varchar(nullif(trim("NATIONALITY"::varchar), '')),
               'PARTYDISPLAYNAME', to_varchar(null),
               'PARTYFULLNAME', to_varchar(nullif(trim("FULLNAME"::varchar), '')),
               'PARTYLEGALNAME', to_varchar(null),
               'PARTYSHORTNAME', to_varchar(null),
               'PARTYSTATUS', to_varchar(null),
               'PARTYTYPECODE', to_varchar(null),
               'PLACEOFBIRTH', to_varchar(nullif(trim("BIRTH_PLACE"::varchar), '')),
               'SALUTATION', to_varchar(nullif(trim("PREFIX"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
