),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_IDENTITY' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 127. OPUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 10 column(s) compared. 3 RAW branch(es): stitch
-- stitch_party_individual_demographics, BJAZ_T_CKYC_PERSONAL_DTLS, BJAZ_T_KYC_OCR.
-- stitch_party_individual_demographics reproduced from 8 RAW tables with no watermark
-- window; every row combination per key is kept because the stitch keeps one of them
-- arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, iff(s.RECORD_SOURCE in ('OPUS_BJAZ_T_CKYC_PERSONAL_DTLS', 'OPUS_BJAZ_T_KYC_OCR'), s.RECORD_SOURCE, 'STITCH') as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ANNUALHOUSEHOLDINCOME', to_varchar(s."ANNUALHOUSEHOLDINCOME"),
               'ANNUALINCOME', to_varchar(s."ANNUALINCOME"),
               'DESIGNATION', to_varchar(s."DESIGNATION"),
               'EDUCATIONALQUALIFICATION', to_varchar(s."EDUCATIONALQUALIFICATION"),
               'FATHERNAME', to_varchar(s."FATHERNAME"),
               'MARITALSTATUS', to_varchar(s."MARITALSTATUS"),
               'NUMBEROFCHILDREN', to_varchar(s."NUMBEROFCHILDREN"),
               'OCCUPATIONCODE', to_varchar(s."OCCUPATIONCODE"),
               'OCCUPATIONDESCRIPTION', to_varchar(s."OCCUPATIONDESCRIPTION"),
               'SPOUSENAME', to_varchar(s."SPOUSENAME")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_party_individual_demographics: every key of every contributing table (no watermark window)
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_AZBJ_PARTNER_EXTN
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("FAMILY_MONTHLY_INCOME"::varchar), ''))), '') as "ANNUALHOUSEHOLDINCOME",
           nullif(trim(to_varchar(nullif(trim("EDUCATION"::varchar), ''))), '') as "EDUCATIONALQUALIFICATION",
           nullif(trim(to_varchar(nullif(trim("FATHER_NAME"::varchar), ''))), '') as "FATHERNAME",
           nullif(trim(to_varchar(("NO_OF_CHILDREN"::number))), '') as "NUMBEROFCHILDREN",
           nullif(trim(to_varchar(nullif(trim("OCCUPATION_DESC_GEN"::varchar), ''))), '') as "OCCUPATIONDESCRIPTION",
           nullif(trim(to_varchar(nullif(trim("SPOUSE_NAME"::varchar), ''))), '') as "SPOUSENAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t3 as (
    -- OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as "ANNUALINCOME",
           nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t4 as (
    -- OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("MONTHLY_INCOME"::number))), '') as "ANNUALINCOME",
           nullif(trim(to_varchar(nullif(trim("MEMBER_OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t5 as (
    -- OPUS_BJAZ_HC_PART_EXTN
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t6 as (
    -- OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as "ANNUALINCOME",
           nullif(trim(to_varchar(nullif(trim("DESIGNATION"::varchar), ''))), '') as "DESIGNATION",
           nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t7 as (
    -- OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as "ANNUALINCOME",
           nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t8 as (
    -- OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("MEMBER_OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t9 as (
    -- OPUS_CP_PARTNERS
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("MARITAL_STATUS"::varchar), ''))), '') as "MARITALSTATUS",
           nullif(trim(to_varchar(nullif(trim("OCCUPATION"::varchar), ''))), '') as "OCCUPATIONCODE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           st1_t0."ANNUALHOUSEHOLDINCOME" as "ANNUALHOUSEHOLDINCOME",
           coalesce(st1_t3."ANNUALINCOME", st1_t4."ANNUALINCOME", st1_t6."ANNUALINCOME", st1_t7."ANNUALINCOME") as "ANNUALINCOME",
           st1_t6."DESIGNATION" as "DESIGNATION",
           st1_t0."EDUCATIONALQUALIFICATION" as "EDUCATIONALQUALIFICATION",
           st1_t0."FATHERNAME" as "FATHERNAME",
           st1_t9."MARITALSTATUS" as "MARITALSTATUS",
           st1_t0."NUMBEROFCHILDREN" as "NUMBEROFCHILDREN",
           coalesce(st1_t3."OCCUPATIONCODE", st1_t4."OCCUPATIONCODE", st1_t5."OCCUPATIONCODE", st1_t6."OCCUPATIONCODE", st1_t7."OCCUPATIONCODE", st1_t8."OCCUPATIONCODE", st1_t9."OCCUPATIONCODE") as "OCCUPATIONCODE",
           st1_t0."OCCUPATIONDESCRIPTION" as "OCCUPATIONDESCRIPTION",
           st1_t0."SPOUSENAME" as "SPOUSENAME",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when st1_t4."PARENT_BK" is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when st1_t5."PARENT_BK" is not null then 'OPUS_BJAZ_HC_PART_EXTN' end,
               case when st1_t6."PARENT_BK" is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when st1_t7."PARENT_BK" is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when st1_t8."PARENT_BK" is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end,
               case when st1_t9."PARENT_BK" is not null then 'OPUS_CP_PARTNERS' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t3."LDTS", st1_t4."LDTS", st1_t5."LDTS", st1_t6."LDTS", st1_t7."LDTS", st1_t8."LDTS", st1_t9."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
      left join st1_t4 on st1_t4."PARENT_BK" = ak."PARENT_BK"
      left join st1_t5 on st1_t5."PARENT_BK" = ak."PARENT_BK"
      left join st1_t6 on st1_t6."PARENT_BK" = ak."PARENT_BK"
      left join st1_t7 on st1_t7."PARENT_BK" = ak."PARENT_BK"
      left join st1_t8 on st1_t8."PARENT_BK" = ak."PARENT_BK"
      left join st1_t9 on st1_t9."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_party_individual_demographics  via stg2_party_individual_demographics <- stitch_party_individual_demographics
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'ANNUALHOUSEHOLDINCOME', to_varchar("ANNUALHOUSEHOLDINCOME"),
               'ANNUALINCOME', to_varchar("ANNUALINCOME"),
               'DESIGNATION', to_varchar("DESIGNATION"),
               'EDUCATIONALQUALIFICATION', to_varchar("EDUCATIONALQUALIFICATION"),
               'FATHERNAME', to_varchar("FATHERNAME"),
               'MARITALSTATUS', to_varchar("MARITALSTATUS"),
               'NUMBEROFCHILDREN', to_varchar("NUMBEROFCHILDREN"),
               'OCCUPATIONCODE', to_varchar("OCCUPATIONCODE"),
               'OCCUPATIONDESCRIPTION', to_varchar("OCCUPATIONDESCRIPTION"),
               'SPOUSENAME', to_varchar("SPOUSENAME")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_individual_demographics <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'ANNUALHOUSEHOLDINCOME', to_varchar(null),
               'ANNUALINCOME', to_varchar(null),
               'DESIGNATION', to_varchar(null),
               'EDUCATIONALQUALIFICATION', to_varchar(null),
               'FATHERNAME', to_varchar(nullif(trim("FATHER_FULLNAME"::varchar), '')),
               'MARITALSTATUS', to_varchar(nullif(trim("MARITAL_STATUS"::varchar), '')),
               'NUMBEROFCHILDREN', to_varchar(null),
               'OCCUPATIONCODE', to_varchar(nullif(trim("OCCUPATION"::varchar), '')),
               'OCCUPATIONDESCRIPTION', to_varchar(null),
               'SPOUSENAME', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_KYC_OCR  via stg2_sat_bjaz_t_kyc_ocr__party_individual_demographics <- stg_partner__bjaz_t_kyc_ocr
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(upper(trim(coalesce(nullif(trim("FIELD_TYPE"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("FIELD_VALUE"::varchar), ''),''))), ':'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_OCR' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'ANNUALHOUSEHOLDINCOME', to_varchar(null),
               'ANNUALINCOME', to_varchar(null),
               'DESIGNATION', to_varchar(null),
               'EDUCATIONALQUALIFICATION', to_varchar(null),
               'FATHERNAME', to_varchar(nullif(trim("FATHER"::varchar), '')),
               'MARITALSTATUS', to_varchar(null),
               'NUMBEROFCHILDREN', to_varchar(null),
               'OCCUPATIONCODE', to_varchar(null),
               'OCCUPATIONDESCRIPTION', to_varchar(null),
               'SPOUSENAME', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 128. OPUS — SAT_PARTY_KYC   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 8 column(s) compared. 5 RAW branch(es):
-- BJAZ_T_CKYC_PERSONAL_DTLS, BJAZ_T_CKYC_REL_PERSION_DTLS, BJAZ_T_CKYC_SEARCH,
-- BJAZ_T_KYC_DETAILS, BJAZ_T_KYC_INCOMING.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'CKYCNUMBER', to_varchar(s."CKYCNUMBER"),
               'CKYCREGISTRATIONSTATUS', to_varchar(s."CKYCREGISTRATIONSTATUS"),
               'KYCCOMPLETIONDATE', to_varchar(s."KYCCOMPLETIONDATE"),
               'KYCMODE', to_varchar(s."KYCMODE"),
               'KYCSTATUS', to_varchar(s."KYCSTATUS"),
               'KYCTYPE', to_varchar(s."KYCTYPE"),
               'LASTKYCREVIEWDATE', to_varchar(s."LASTKYCREVIEWDATE"),
               'OVDSUBMITTEDCOUNT', to_varchar(s."OVDSUBMITTEDCOUNT")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_kyc <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CKYCNUMBER', to_varchar(null),
               'CKYCREGISTRATIONSTATUS', to_varchar(null),
               'KYCCOMPLETIONDATE', to_varchar(null),
               'KYCMODE', to_varchar(null),
               'KYCSTATUS', to_varchar(null),
               'KYCTYPE', to_varchar(nullif(trim("ACC_TYPE"::varchar), '')),
               'LASTKYCREVIEWDATE', to_varchar(null),
               'OVDSUBMITTEDCOUNT', to_varchar(nullif(trim("NUM_IDENTITY"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_CKYC_REL_PERSION_DTLS  via stg2_sat_bjaz_t_ckyc_rel_persion_dtls__party_kyc__related_person <- stg_partner__bjaz_t_ckyc_rel_persion_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CKYCNUMBER', to_varchar(null),
               'CKYCREGISTRATIONSTATUS', to_varchar(null),
               'KYCCOMPLETIONDATE', to_varchar(nullif(trim("DEC_DATE"::varchar), '')),
               'KYCMODE', to_varchar(null),
               'KYCSTATUS', to_varchar(null),
               'KYCTYPE', to_varchar(null),
               'LASTKYCREVIEWDATE', to_varchar(null),
               'OVDSUBMITTEDCOUNT', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_REL_PERSION_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_CKYC_SEARCH  via stg2_sat_bjaz_t_ckyc_search__party_kyc <- stg_partner__bjaz_t_ckyc_search
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(upper(trim(coalesce(nullif(trim("CATEGORY"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("INPUT"::varchar), ''),''))), ':'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_SEARCH' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CKYCNUMBER', to_varchar(nullif(trim("CKYC_NUMBER"::varchar), '')),
               'CKYCREGISTRATIONSTATUS', to_varchar(nullif(trim("CKYC_STATUS"::varchar), '')),
               'KYCCOMPLETIONDATE', to_varchar(nullif(trim("CKYC_KYC_DATE"::varchar), '')),
               'KYCMODE', to_varchar(null),
               'KYCSTATUS', to_varchar(null),
               'KYCTYPE', to_varchar(null),
               'LASTKYCREVIEWDATE', to_varchar(nullif(trim("CKYC_UPDATE_DATE"::varchar), '')),
               'OVDSUBMITTEDCOUNT', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_T_KYC_DETAILS  via stg2_sat_bjaz_t_kyc_details__party_kyc <- stg_partner__bjaz_t_kyc_details
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(upper(trim(coalesce(nullif(trim("CATEGORY"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("INPUT"::varchar), ''),''))), ':'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_DETAILS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CKYCNUMBER', to_varchar(null),
               'CKYCREGISTRATIONSTATUS', to_varchar(null),
               'KYCCOMPLETIONDATE', to_varchar(nullif(trim("KYC_DATE"::varchar), '')),
               'KYCMODE', to_varchar(null),
               'KYCSTATUS', to_varchar(nullif(trim("KYC_STATUS"::varchar), '')),
               'KYCTYPE', to_varchar(null),
               'LASTKYCREVIEWDATE', to_varchar(null),
               'OVDSUBMITTEDCOUNT', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_T_KYC_INCOMING  via stg2_sat_bjaz_t_kyc_incoming__party_kyc <- stg_partner__bjaz_t_kyc_incoming
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(upper(trim(coalesce(nullif(trim("SEARCH_CATEGORY"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("SEARCH_INPUT"::varchar), ''),''))), ':'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_INCOMING' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CKYCNUMBER', to_varchar(null),
               'CKYCREGISTRATIONSTATUS', to_varchar(null),
               'KYCCOMPLETIONDATE', to_varchar(null),
               'KYCMODE', to_varchar(nullif(trim("KYC_MODE"::varchar), '')),
               'KYCSTATUS', to_varchar(null),
               'KYCTYPE', to_varchar(nullif(trim("KYC_TYPE"::varchar), '')),
               'LASTKYCREVIEWDATE', to_varchar(null),
               'OVDSUBMITTEDCOUNT', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_KYC' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 129. OPUS — SAT_PARTY_KYC_REFERENCE   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 1 column(s) compared. 4 RAW branch(es): CP_PARTNERS,
-- BJAZ_T_CKYC_OTP, BJAZ_T_CKYC_SEARCH, BJAZ_T_CKYC_REL_PERSION_DTLS.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'KYCREFERENCETYPE', to_varchar(s."KYCREFERENCETYPE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_KYC_REFERENCE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. CP_PARTNERS  via stg2_sat_cp_partners__party_kyc_reference <- stg_partner__cp_partners
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_CP_PARTNERS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'KYCREFERENCETYPE', to_varchar(nullif(trim("EVID_TYPE"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_CKYC_OTP  via stg2_sat_bjaz_t_ckyc_otp__party_kyc_reference <- stg_partner__bjaz_t_ckyc_otp
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(upper(trim(coalesce(nullif(trim("CATEGORY"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("INPUT"::varchar), ''),''))), ':'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_OTP' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'KYCREFERENCETYPE', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_OTP
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_CKYC_SEARCH  via stg2_sat_bjaz_t_ckyc_search__party_kyc_reference <- stg_partner__bjaz_t_ckyc_search
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(upper(trim(coalesce(nullif(trim("CATEGORY"::varchar), ''),''))) || ':' || upper(trim(coalesce(nullif(trim("INPUT"::varchar), ''),''))), ':'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_SEARCH' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'KYCREFERENCETYPE', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_SEARCH
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_T_CKYC_REL_PERSION_DTLS  via stg2_sat_bjaz_t_ckyc_rel_persion_dtls__party_kyc_reference__related_person <- stg_partner__bjaz_t_ckyc_rel_persion_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'KYCREFERENCETYPE', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_REL_PERSION_DTLS
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_KYC_REFERENCE' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 130. OPUS — SAT_PARTY_ORGANISATION_PROFILE   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 8 column(s) compared. 3 RAW branch(es): stitch
-- stitch_party_organisation_profile, BJAZ_M_KYC_GSTN, BJAZ_T_CKYC_PERSONAL_DTLS.
-- stitch_party_organisation_profile reproduced from 3 RAW tables with no watermark
-- window; every row combination per key is kept because the stitch keeps one of them
-- arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, iff(s.RECORD_SOURCE in ('OPUS_BJAZ_M_KYC_GSTN', 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS'), s.RECORD_SOURCE, 'STITCH') as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ANNUALTURNOVER', to_varchar(s."ANNUALTURNOVER"),
               'DATEOFINCORPORATION', to_varchar(s."DATEOFINCORPORATION"),
               'GROUPNAME', to_varchar(s."GROUPNAME"),
               'INDUSTRYDESCRIPTION', to_varchar(s."INDUSTRYDESCRIPTION"),
               'LEGALCONSTITUTIONTYPE', to_varchar(s."LEGALCONSTITUTIONTYPE"),
               'MSMEINDICATOR', to_varchar(s."MSMEINDICATOR"),
               'PAIDUPCAPITAL', to_varchar(s."PAIDUPCAPITAL"),
               'PARENTENTITYNAME', to_varchar(s."PARENTENTITYNAME")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORGANISATION_PROFILE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_party_organisation_profile: every key of every contributing table (no watermark window)
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("PART_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_AZBJ_PARTNER_EXTN
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("GLOBAL_CO_NAME"::varchar), ''))), '') as "GROUPNAME",
           nullif(trim(to_varchar(("INDUSTRY"::number))), '') as "INDUSTRYDESCRIPTION",
           nullif(trim(to_varchar(nullif(trim("MSME_FLAG"::varchar), ''))), '') as "MSMEINDICATOR",
           nullif(trim(to_varchar(("PAIDUP_CAPITAL"::number))), '') as "PAIDUPCAPITAL",
           nullif(trim(to_varchar(nullif(trim("PARENT_CO"::varchar), ''))), '') as "PARENTENTITYNAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t2 as (
    -- OPUS_BJAZ_CLM_SUPP_EXTN
    select distinct nullif(trim("PARTNER_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("ANN_TURNOVER"::varchar), ''))), '') as "ANNUALTURNOVER",
           nullif(trim(to_varchar(nullif(trim("ESTABLISH_YEAR"::varchar), ''))), '') as "DATEOFINCORPORATION",
           nullif(trim(to_varchar(nullif(trim("MSME_CLASS"::varchar), ''))), '') as "MSMEINDICATOR",
           nullif(trim(to_varchar(nullif(trim("PARENT_CO_NAME"::varchar), ''))), '') as "PARENTENTITYNAME",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where nullif(trim("PARTNER_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t4 as (
    -- OPUS_CP_PARTNERS
    select distinct nullif(trim("PART_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("LEGAL_FORM"::varchar), ''))), '') as "LEGALCONSTITUTIONTYPE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where nullif(trim("PART_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           st1_t2."ANNUALTURNOVER" as "ANNUALTURNOVER",
           st1_t2."DATEOFINCORPORATION" as "DATEOFINCORPORATION",
           st1_t0."GROUPNAME" as "GROUPNAME",
           st1_t0."INDUSTRYDESCRIPTION" as "INDUSTRYDESCRIPTION",
           st1_t4."LEGALCONSTITUTIONTYPE" as "LEGALCONSTITUTIONTYPE",
           coalesce(st1_t0."MSMEINDICATOR", st1_t2."MSMEINDICATOR") as "MSMEINDICATOR",
           st1_t0."PAIDUPCAPITAL" as "PAIDUPCAPITAL",
           coalesce(st1_t0."PARENTENTITYNAME", st1_t2."PARENTENTITYNAME") as "PARENTENTITYNAME",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when st1_t2."PARENT_BK" is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when st1_t4."PARENT_BK" is not null then 'OPUS_CP_PARTNERS' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t2."LDTS", st1_t4."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t2 on st1_t2."PARENT_BK" = ak."PARENT_BK"
      left join st1_t4 on st1_t4."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_party_organisation_profile  via stg2_party_organisation_profile <- stitch_party_organisation_profile
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'ANNUALTURNOVER', to_varchar("ANNUALTURNOVER"),
               'DATEOFINCORPORATION', to_varchar("DATEOFINCORPORATION"),
               'GROUPNAME', to_varchar("GROUPNAME"),
               'INDUSTRYDESCRIPTION', to_varchar("INDUSTRYDESCRIPTION"),
               'LEGALCONSTITUTIONTYPE', to_varchar("LEGALCONSTITUTIONTYPE"),
               'MSMEINDICATOR', to_varchar("MSMEINDICATOR"),
               'PAIDUPCAPITAL', to_varchar("PAIDUPCAPITAL"),
               'PARENTENTITYNAME', to_varchar("PARENTENTITYNAME")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_M_KYC_GSTN  via stg2_sat_bjaz_m_kyc_gstn__party_organisation_profile <- stg_partner__bjaz_m_kyc_gstn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('GSTIN:' || upper(trim(coalesce(nullif(trim("GSTIN_NUMBER"::varchar), ''),''))), 'GSTIN:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_M_KYC_GSTN' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'ANNUALTURNOVER', to_varchar(null),
               'DATEOFINCORPORATION', to_varchar(null),
               'GROUPNAME', to_varchar(null),
               'INDUSTRYDESCRIPTION', to_varchar(null),
               'LEGALCONSTITUTIONTYPE', to_varchar(nullif(trim("BUSINESS_TYPE"::varchar), '')),
               'MSMEINDICATOR', to_varchar(null),
               'PAIDUPCAPITAL', to_varchar(null),
               'PARENTENTITYNAME', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_CKYC_PERSONAL_DTLS  via stg2_sat_bjaz_t_ckyc_personal_dtls__party_organisation_profile <- stg_partner__bjaz_t_ckyc_personal_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif('CKYC:' || upper(trim(coalesce(nullif(trim("CKYC_NO"::varchar), ''),''))), 'CKYC:'))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'ANNUALTURNOVER', to_varchar(null),
               'DATEOFINCORPORATION', to_varchar(null),
               'GROUPNAME', to_varchar(null),
               'INDUSTRYDESCRIPTION', to_varchar(null),
               'LEGALCONSTITUTIONTYPE', to_varchar(null),
               'MSMEINDICATOR', to_varchar(null),
               'PAIDUPCAPITAL', to_varchar(null),
               'PARENTENTITYNAME', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_ORGANISATION_PROFILE' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 131. OPUS — SAT_PARTY_VEHICLE_PRIOR_INSURANCE   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 5 column(s) compared. 8 RAW branch(es): BJAZ_CTNGY_PA_MEM_DTLS,
-- BJAZ_EC_MEM_DTLS_EXTN, BJAZ_HCF_MEMBER_DTLS, BJAZ_HC_PART_EXTN,
-- BJAZ_HLT_ENSURE_MEM_DTLS, BJAZ_PA_DETL_EXTN, BJAZ_SH_MEM_DTLS_EXTN,
-- BJAZ_SPP_MEMBER_DTLS.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.PARTY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(s."CONTINUITYINDICATOR"),
               'PREVIOUSEXPIRYDATE', to_varchar(s."PREVIOUSEXPIRYDATE"),
               'PREVIOUSINSURERNAME', to_varchar(s."PREVIOUSINSURERNAME"),
               'PREVIOUSPOLICYNUMBER', to_varchar(s."PREVIOUSPOLICYNUMBER"),
               'PREVIOUSSUMINSURED', to_varchar(s."PREVIOUSSUMINSURED")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_VEHICLE_PRIOR_INSURANCE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BJAZ_CTNGY_PA_MEM_DTLS  via stg2_sat_bjaz_ctngy_pa_mem_dtls__party_vehicle_prior_insurance <- stg_partner__bjaz_ctngy_pa_mem_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(null),
               'PREVIOUSEXPIRYDATE', to_varchar(null),
               'PREVIOUSINSURERNAME', to_varchar(null),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("PREVIOUS_POLICY_DETAILS"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_EC_MEM_DTLS_EXTN  via stg2_sat_bjaz_ec_mem_dtls_extn__party_vehicle_prior_insurance <- stg_partner__bjaz_ec_mem_dtls_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_EC_MEM_DTLS_EXTN' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(null),
               'PREVIOUSEXPIRYDATE', to_varchar(nullif(trim("PERV_POL_EXP_DATE"::varchar), '')),
               'PREVIOUSINSURERNAME', to_varchar(nullif(trim("PREV_COMPANY_NAME"::varchar), '')),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("PREV_POLICY_DTLS"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(("PREV_SUM_INSURED"::number))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_HCF_MEMBER_DTLS  via stg2_sat_bjaz_hcf_member_dtls__party_vehicle_prior_insurance <- stg_partner__bjaz_hcf_member_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HCF_MEMBER_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(("PREV_POLICY_SINCE"::timestamp_ntz)),
               'PREVIOUSEXPIRYDATE', to_varchar(null),
               'PREVIOUSINSURERNAME', to_varchar(null),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("CONCURRENT_POLICY_DETAILS"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(("PREVIOUS_SI"::number))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_HC_PART_EXTN  via stg2_sat_bjaz_hc_part_extn__party_vehicle_prior_insurance <- stg_partner__bjaz_hc_part_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PART_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HC_PART_EXTN' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(null),
               'PREVIOUSEXPIRYDATE', to_varchar(null),
               'PREVIOUSINSURERNAME', to_varchar(null),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("FIRST_POLICY_REF"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 5. BJAZ_HLT_ENSURE_MEM_DTLS  via stg2_sat_bjaz_hlt_ensure_mem_dtls__party_vehicle_prior_insurance <- stg_partner__bjaz_hlt_ensure_mem_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(nullif(trim("PREVIOUS_SINCE_NOOF_YEARS"::varchar), '')),
               'PREVIOUSEXPIRYDATE', to_varchar(nullif(trim("PREVIOUS_TO_DATE"::varchar), '')),
               'PREVIOUSINSURERNAME', to_varchar(nullif(trim("PREVIOUS_COMPANY_NAME"::varchar), '')),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("PREV_POLICY_NO"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(nullif(trim("PREVIOUS_SUM_INSURED"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 6. BJAZ_PA_DETL_EXTN  via stg2_sat_bjaz_pa_detl_extn__party_vehicle_prior_insurance <- stg_partner__bjaz_pa_detl_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_PA_DETL_EXTN' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(null),
               'PREVIOUSEXPIRYDATE', to_varchar(null),
               'PREVIOUSINSURERNAME', to_varchar(null),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("FIRST_POLICY_REF"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 7. BJAZ_SH_MEM_DTLS_EXTN  via stg2_sat_bjaz_sh_mem_dtls_extn__party_vehicle_prior_insurance <- stg_partner__bjaz_sh_mem_dtls_extn
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SH_MEM_DTLS_EXTN' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(null),
               'PREVIOUSEXPIRYDATE', to_varchar(null),
               'PREVIOUSINSURERNAME', to_varchar(null),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("PREV_POLICY_DTLS"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(("PREV_SUM_INSURED"::number))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 8. BJAZ_SPP_MEMBER_DTLS  via stg2_sat_bjaz_spp_member_dtls__party_vehicle_prior_insurance <- stg_partner__bjaz_spp_member_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_PARTY|' || (nullif(trim("PARTNER_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SPP_MEMBER_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'CONTINUITYINDICATOR', to_varchar(("PREV_POLICY_SINCE"::timestamp_ntz)),
               'PREVIOUSEXPIRYDATE', to_varchar(null),
               'PREVIOUSINSURERNAME', to_varchar(null),
               'PREVIOUSPOLICYNUMBER', to_varchar(nullif(trim("CONCURRENT_POLICY_DETAILS"::varchar), '')),
               'PREVIOUSSUMINSURED', to_varchar(("PREVIOUS_SI"::number))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_PARTY_VEHICLE_PRIOR_INSURANCE' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 132. OPUS — SAT_POLICY_BONUS_TRACKING   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 2 column(s) compared. 1 RAW branch(es): stitch
-- stitch_policy_bonus_tracking. stitch_policy_bonus_tracking reproduced from 7 RAW
-- tables with no watermark window; every row combination per key is kept because the
-- stitch keeps one of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'BONUSAMOUNT', to_varchar(s."BONUSAMOUNT"),
               'CUMULATIVEBONUSPERCENTAGE', to_varchar(s."CUMULATIVEBONUSPERCENTAGE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_BONUS_TRACKING s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_policy_bonus_tracking: every key of every contributing table (no watermark window)
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
    union
    select nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t0 as (
    -- OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("PRE_POL_NCB_PER"::number))), '') as "CUMULATIVEBONUSPERCENTAGE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t1 as (
    -- OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("CUMULATIVE_AMT"::number))), '') as "BONUSAMOUNT",
           nullif(trim(to_varchar(("CUMULATIVE_BNOUZ_PER"::number))), '') as "CUMULATIVEBONUSPERCENTAGE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t2 as (
    -- OPUS_BJAZ_HLT_ENSURE_MEM_DTLS
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("PREVIOUS_CUM_BONUS"::varchar), ''))), '') as "BONUSAMOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t3 as (
    -- OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("BONUS_SI"::number))), '') as "BONUSAMOUNT",
           nullif(trim(to_varchar(("CUMM_BONUS_PER"::number))), '') as "CUMULATIVEBONUSPERCENTAGE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t4 as (
    -- OPUS_BJAZ_PA_DETL_EXTN
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(nullif(trim("CUMMULATIVE_BONUS"::varchar), ''))), '') as "BONUSAMOUNT",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PA_DETL_EXTN
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t5 as (
    -- OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("CUMM_BONUS"::number))), '') as "BONUSAMOUNT",
           nullif(trim(to_varchar(("CUMM_BONUS_PER"::number))), '') as "CUMULATIVEBONUSPERCENTAGE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1_t6 as (
    -- OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct nullif(trim("CONTRACT_ID"::varchar), '') as "PARENT_BK",
           nullif(trim(to_varchar(("CUMULATIVE_AMT"::number))), '') as "BONUSAMOUNT",
           nullif(trim(to_varchar(("CUMULATIVE_BNOUZ_PER"::number))), '') as "CUMULATIVEBONUSPERCENTAGE",
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as "LDTS"
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where nullif(trim("CONTRACT_ID"::varchar), '') is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) in (select hkey from sample_keys)
),
st1 as (
    -- every row combination per key (the stitch keeps one of them; the vault row must equal one)
    select ak."PARENT_BK",
           coalesce(st1_t1."BONUSAMOUNT", st1_t2."BONUSAMOUNT", st1_t3."BONUSAMOUNT", st1_t4."BONUSAMOUNT", st1_t5."BONUSAMOUNT", st1_t6."BONUSAMOUNT") as "BONUSAMOUNT",
           coalesce(st1_t0."CUMULATIVEBONUSPERCENTAGE", st1_t1."CUMULATIVEBONUSPERCENTAGE", st1_t3."CUMULATIVEBONUSPERCENTAGE", st1_t5."CUMULATIVEBONUSPERCENTAGE", st1_t6."CUMULATIVEBONUSPERCENTAGE") as "CUMULATIVEBONUSPERCENTAGE",
           array_to_string(array_construct_compact(
               case when st1_t0."PARENT_BK" is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when st1_t1."PARENT_BK" is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when st1_t2."PARENT_BK" is not null then 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS' end,
               case when st1_t3."PARENT_BK" is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when st1_t4."PARENT_BK" is not null then 'OPUS_BJAZ_PA_DETL_EXTN' end,
               case when st1_t5."PARENT_BK" is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when st1_t6."PARENT_BK" is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end
           ), ', ') as "RECORD_SOURCE",
           greatest_ignore_nulls(st1_t0."LDTS", st1_t1."LDTS", st1_t2."LDTS", st1_t3."LDTS", st1_t4."LDTS", st1_t5."LDTS", st1_t6."LDTS") as "INC_JOB_UPDATED_AT"
      from st1_ak ak
      left join st1_t0 on st1_t0."PARENT_BK" = ak."PARENT_BK"
      left join st1_t1 on st1_t1."PARENT_BK" = ak."PARENT_BK"
      left join st1_t2 on st1_t2."PARENT_BK" = ak."PARENT_BK"
      left join st1_t3 on st1_t3."PARENT_BK" = ak."PARENT_BK"
      left join st1_t4 on st1_t4."PARENT_BK" = ak."PARENT_BK"
      left join st1_t5 on st1_t5."PARENT_BK" = ak."PARENT_BK"
      left join st1_t6 on st1_t6."PARENT_BK" = ak."PARENT_BK"
),
src as (
    -- 1. stitch stitch_policy_bonus_tracking  via stg2_policy_bonus_tracking <- stitch_policy_bonus_tracking
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || "PARENT_BK") AS VARCHAR))), '')) as hkey,
           'STITCH' as rs_key,
           "INC_JOB_UPDATED_AT" as ldts,
           object_construct_keep_null(
               'BONUSAMOUNT', to_varchar("BONUSAMOUNT"),
               'CUMULATIVEBONUSPERCENTAGE', to_varchar("CUMULATIVEBONUSPERCENTAGE")
           ) as obj
      from st1
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_POLICY_BONUS_TRACKING' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 133. OPUS — SAT_POLICY_CERTIFICATE   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 2 column(s) compared. 3 RAW branch(es): BA_HCP_DT_MEM,
-- BJAZ_CTNGY_PA_MEM_DTLS, BJAZ_HM_MEMBER_DTLS.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'ENROLMENTDATE', to_varchar(s."ENROLMENTDATE"),
               'MEMBERSTATUS', to_varchar(s."MEMBERSTATUS")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CERTIFICATE s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BA_HCP_DT_MEM  via stg2_sat_ba_hcp_dt_mem__policy_certificate <- stg_partner__ba_hcp_dt_mem
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BA_HCP_DT_MEM' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'ENROLMENTDATE', to_varchar(null),
               'MEMBERSTATUS', to_varchar(nullif(trim("MEM_STATUS"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BA_HCP_DT_MEM
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_CTNGY_PA_MEM_DTLS  via stg2_sat_bjaz_ctngy_pa_mem_dtls__policy_certificate <- stg_partner__bjaz_ctngy_pa_mem_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_CTNGY_PA_MEM_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'ENROLMENTDATE', to_varchar(("PM_POL_ENROLMENT_DATE"::timestamp_ntz)),
               'MEMBERSTATUS', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_HM_MEMBER_DTLS  via stg2_sat_bjaz_hm_member_dtls__policy_certificate <- stg_partner__bjaz_hm_member_dtls
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_HM_MEMBER_DTLS' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'ENROLMENTDATE', to_varchar(null),
               'MEMBERSTATUS', to_varchar(nullif(trim("MEMBER_STATUS"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           0 as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and true then 'MATCH'
                when boolean_and_agg(m.value_match) and true then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_POLICY_CERTIFICATE' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



----------------------------------------------------------------------------------------
-- 134. OPUS — SAT_POLICY_CLASSIFICATION   [Implemented]
-- Mode -- multi-active: the current vault set and the latest source set of each (hash
-- key, record source) must contain the same rows. 2 column(s) compared. 4 RAW
-- branch(es): BJAZ_T_KYC_DETAILS, BJAZ_T_KYC_INCOMING, BJAZ_T_KYC_POA_DOCUMENT,
-- BJAZ_T_KYC_POI_DOCUMENT.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'CLASSIFICATIONTYPE', to_varchar(s."CLASSIFICATIONTYPE"),
               'CLASSIFICATIONVALUE', to_varchar(s."CLASSIFICATIONVALUE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_CLASSIFICATION s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
src as (
    -- 1. BJAZ_T_KYC_DETAILS  via stg2_sat_bjaz_t_kyc_details__policy_classification <- stg_partner__bjaz_t_kyc_details
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (upper(case when upper(trim(nullif(trim("FIELD_TYPE"::varchar), ''))) like 'POLICY%' then trim(nullif(trim("FIELD_VALUE"::varchar), '')) end))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_DETAILS' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CLASSIFICATIONTYPE', to_varchar('BUSINESS_TYPE'),
               'CLASSIFICATIONVALUE', to_varchar(nullif(trim("BUSINESS_TYPE"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_DETAILS
     where 'BUSINESS_TYPE' is not null
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 2. BJAZ_T_KYC_INCOMING  via stg2_sat_bjaz_t_kyc_incoming__policy_classification <- stg_partner__bjaz_t_kyc_incoming
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (case when upper(trim(nullif(trim("FIELD_TYPE"::varchar), ''))) like 'POLICY%' then trim(nullif(trim("FIELD_VALUE"::varchar), '')) end)) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_INCOMING' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CLASSIFICATIONTYPE', to_varchar('BUSINESS_TYPE'),
               'CLASSIFICATIONVALUE', to_varchar(nullif(trim("BUSINESS_TYPE"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING
     where 'BUSINESS_TYPE' is not null
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 3. BJAZ_T_KYC_POA_DOCUMENT  via stg2_sat_bjaz_t_kyc_poa_document__policy_classification <- stg_partner__bjaz_t_kyc_poa_document
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (upper(case when upper(trim(nullif(trim("FIELD_TYPE"::varchar), ''))) like 'POLICY%' then trim(nullif(trim("FIELD_VALUE"::varchar), '')) end))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_POA_DOCUMENT' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CLASSIFICATIONTYPE', to_varchar('BUSINESS_TYPE'),
               'CLASSIFICATIONVALUE', to_varchar(nullif(trim("BUSINESS_TYPE"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POA_DOCUMENT
     where 'BUSINESS_TYPE' is not null
    ) where hkey in (select hkey from sample_keys)
    union all
    -- 4. BJAZ_T_KYC_POI_DOCUMENT  via stg2_sat_bjaz_t_kyc_poi_document__policy_classification <- stg_partner__bjaz_t_kyc_poi_document
    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (upper(case when upper(trim(nullif(trim("FIELD_TYPE"::varchar), ''))) like 'POLICY%' then trim(nullif(trim("FIELD_VALUE"::varchar), '')) end))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_T_KYC_POI_DOCUMENT' as rs_key,
           to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', '')) as ldts,
           object_construct_keep_null(
               'CLASSIFICATIONTYPE', to_varchar('BUSINESS_TYPE'),
               'CLASSIFICATIONVALUE', to_varchar(nullif(trim("BUSINESS_TYPE"::varchar), ''))
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_POI_DOCUMENT
     where 'BUSINESS_TYPE' is not null
    ) where hkey in (select hkey from sample_keys)
),
src_n as (
    select s.*, row_number() over (order by s.hkey, s.ldts) as src_row_id from src s
),
src_cols as (
    select s.src_row_id, s.hkey, s.rs_key, f.key as col, as_varchar(f.value) as val
      from src_n s, lateral flatten(input => s.obj) f
),
pairs as (
    -- every (vault row, source row) pair of a sampled unit, with the number of differing columns
    select a.sat_row_id, b.src_row_id, a.hkey, a.rs,
           count_if(not equal_null(a.val, b.val)) as n_diff_exact,
           count_if(not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))) as n_diff
      from sat_cols a
      join src_cols b on b.hkey = a.hkey and b.rs_key = a.rs_key and b.col = a.col
     group by a.sat_row_id, b.src_row_id, a.hkey, a.rs
),
sat_match as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts,
           coalesce(min(p.n_diff_exact) = 0, false) as exact_match,
           coalesce(min(p.n_diff) = 0, false) as value_match
      from sat_sample c
      left join pairs p on p.sat_row_id = c.sat_row_id
     group by c.sat_row_id, c.hkey, c.rs, c.rs_key, c.ldts
),
src_stats as (
    select hkey, rs_key, count(*) as src_rows, max(ldts) as src_max_ldts from src_n group by hkey, rs_key
),
src_not_in_vault as (
    -- multi-active: every source row of the latest source set must be in the vault's current set
    select u.hkey, u.rs, count(*) as n
      from (select * from src_n qualify rank() over (partition by hkey, rs_key order by ldts desc) = 1) s
      join sample_units u on u.hkey = s.hkey and u.rs_key = s.rs_key
     where not exists (select 1 from pairs p where p.src_row_id = s.src_row_id and p.hkey = u.hkey
                                               and p.rs = u.rs and p.n_diff = 0)
     group by u.hkey, u.rs
),
classified as (
    select m.hkey, m.rs,
           boolean_and_agg(m.exact_match) as all_exact,
           boolean_and_agg(m.value_match) as all_value,
           max(m.ldts) as sat_ldts,
           any_value(st.src_rows) as src_rows,
           any_value(st.src_max_ldts) as src_max_ldts,
           any_value(coalesce(x.n, 0)) as src_rows_not_in_vault,
           case when coalesce(any_value(st.src_rows), 0) = 0 then 'NOT_IN_SOURCE'
                when boolean_and_agg(m.exact_match) and any_value(coalesce(x.n, 0)) = 0 then 'MATCH'
                when boolean_and_agg(m.value_match) and any_value(coalesce(x.n, 0)) = 0 then 'MATCH_DATE_FORMAT'
                when any_value(st.src_max_ldts) > max(m.ldts) then 'SOURCE_CHANGED_AFTER_LOAD'
                else 'MISMATCH' end as unit_status
      from sat_match m
      left join src_stats st on st.hkey = m.hkey and st.rs_key = m.rs_key
      left join src_not_in_vault x on x.hkey = m.hkey and x.rs = m.rs
     group by m.hkey, m.rs
),
best_pair as (
    select p.*
      from pairs p
      join classified k on k.hkey = p.hkey and k.rs = p.rs and k.unit_status = 'MISMATCH'
    qualify row_number() over (partition by p.hkey, p.rs order by p.n_diff, p.sat_row_id, p.src_row_id) = 1
),
examples as (
    -- closest source row of each mismatched unit: the columns that differ
    select hex_encode(a.hkey) || ' [' || a.rs || '] ' || a.col || ': vault=' || coalesce(a.val, 'NULL')
           || ' | source=' || coalesce(b.val, 'NULL') as example
      from best_pair bp
      join sat_cols a on a.sat_row_id = bp.sat_row_id
      join src_cols b on b.src_row_id = bp.src_row_id and b.col = a.col
     where not (equal_null(a.val, b.val) or (a.val like '____-__-__%' and b.val like '____-__-__%' and try_to_timestamp_ntz(a.val) = try_to_timestamp_ntz(b.val)))
    qualify row_number() over (order by a.hkey, a.rs, a.col) <= 20
)
select 'OPUS' as project, 'SAT_POLICY_CLASSIFICATION' as satellite,
       count(*)                                                as sampled_units,
       count_if(unit_status = 'MATCH')                         as matched,
       count_if(unit_status = 'MATCH_DATE_FORMAT')             as matched_date_format_only,
       count_if(unit_status = 'MISMATCH')                      as mismatched,
       count_if(unit_status = 'SOURCE_CHANGED_AFTER_LOAD')     as source_changed_after_load,
       count_if(unit_status = 'NOT_IN_SOURCE')                 as not_in_source,
       case when count(*) = 0 then 'NO DATA'
            when count_if(unit_status = 'MISMATCH') = 0 then 'PASS'
            else 'FAIL' end                                    as status,
       (select listagg(example, ' ;; ') within group (order by example) from examples) as mismatch_examples
  from classified;



