-- 137. OPUS — SAT_POLICY_HEADER   [Implemented]
-- Mode -- single-active: every current vault row must equal one source row of its (hash
-- key, record source). 5 column(s) compared. 1 RAW branch(es): stitch
-- stitch_policy_header. stitch_policy_header reproduced from 10 RAW tables with no
-- watermark window; every row combination per key is kept because the stitch keeps one
-- of them arbitrarily.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, 'STITCH' as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'MASTERPOLICYREFERENCE', to_varchar(s."MASTERPOLICYREFERENCE"),
               'POLICYREFERENCENUMBER', to_varchar(s."POLICYREFERENCENUMBER"),
               'POLICYTERM', to_varchar(s."POLICYTERM"),
               'RISKEXPIRYDATE', to_varchar(s."RISKEXPIRYDATE"),
               'RISKINCEPTIONDATE', to_varchar(s."RISKINCEPTIONDATE")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
      from current_rows c
      join sample_units u on u.hkey = c.hkey and u.rs = c.rs
),
sat_cols as (
    select c.sat_row_id, c.hkey, c.rs, c.rs_key, f.key as col, as_varchar(f.value) as val
      from sat_sample c, lateral flatten(input => c.obj) f
),
st1_ak as (
    -- stitch_policy_header: every key of every contributing table (no watermark window)
    select nullif(trim("EXISTING_POLICY_PID"::varchar), '') as "PARENT_BK"
