           'OPUS_BJAZ_HM_HOSPITAL_MASTER' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'DISCOUNTPERCENTAGE', to_varchar(nullif(trim("IMPS_DISCNT_ON"::varchar), '')),
               'EFFECTIVEDATE', to_varchar(("IMPS_TARIF_FRM"::timestamp_ntz)),
