    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_DISTRIBUTION_CHANNEL|' || (nullif(trim("INTERMEDIARY_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_INTERMEDIARY' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'BLOCKED_FOR_RECEIPT_INDICATOR', to_varchar(nullif(trim("BLOCK_FOR_RECEIPT"::varchar), '')),
               'FINANCE_SUB_CHANNEL_CODE', to_varchar(nullif(trim("FIN_SUB_CHANNEL_CODE"::varchar), '')),
               'GREEN_CHANNEL_INDICATOR', to_varchar(nullif(trim("GREEN_CHANNEL_IMD"::varchar), '')),
               'IMDFLAG', to_varchar(nullif(trim("IMDFLAG"::varchar), '')),
               'NEW_IMD_TYPE', to_varchar(nullif(trim("NEW_IMD_TYPE"::varchar), '')),
               'REVISED_CHANNEL_CODE', to_varchar(nullif(trim("NEW_BC"::varchar), '')),
               'SPECIAL_INTERMEDIARY_CODE', to_varchar(nullif(trim("SPL_INTER_CODE"::varchar), '')),
               'SUBIMD_YN', to_varchar(nullif(trim("SUBIMD_YN"::varchar), '')),
               'SUB_IMD_CODE', to_varchar(null)
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_INTERMEDIARY
    ) where hkey in (select hkey from sample_keys)
