-- 157. OPUS — SAT_AUG_POLICY   [Implemented]
-- Mode -- multi-active: the current vault set and the latest source set of each (hash
-- key, record source) must contain the same rows. 9 column(s) compared. 5 RAW
-- branch(es): BJAZ_HLT_ENSURE_MEM_DTLS, BJAZ_HM_MEMBER_DTLS, BJAZ_PA_DETL_EXTN,
-- BJAZ_EC_MEM_DTLS_EXTN, BJAZ_SH_MEM_DTLS_EXTN.
----------------------------------------------------------------------------------------
with sat_rows as (
    -- this project's rows of the satellite
    select s.POLICY_HKEY as hkey, s.RECORD_SOURCE as rs, s.RECORD_SOURCE as rs_key,
           s.LOAD_DATETIME as ldts,
           object_construct_keep_null(
               'MEMBER_SEQUENCE', to_varchar(s."MEMBER_SEQUENCE"),
               'CUMMULATIVE_AMT', to_varchar(s."CUMMULATIVE_AMT"),
               'CUMM_BONUS', to_varchar(s."CUMM_BONUS"),
               'CUMM_BONUS_AMT_COMP', to_varchar(s."CUMM_BONUS_AMT_COMP"),
               'CUMM_BONUS_AMT_WIDER', to_varchar(s."CUMM_BONUS_AMT_WIDER"),
               'CUMM_BONUS_COMP', to_varchar(s."CUMM_BONUS_COMP"),
               'CUMM_BONUS_WIDER', to_varchar(s."CUMM_BONUS_WIDER"),
               'INCEPTION_DATE', to_varchar(s."INCEPTION_DATE"),
               'PREVIOUS_CUM_AMOUNT', to_varchar(s."PREVIOUS_CUM_AMOUNT")
           ) as obj
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY s
     where startswith(s.RECORD_SOURCE, 'OPUS')
),
current_rows as (
    -- current state per (hash key, record source) = rows at the latest LOAD_DATETIME
    select * from sat_rows
    qualify rank() over (partition by hkey, rs order by ldts desc) = 1
),
sample_units as (
    -- agreed sample: 100 (hash key, record source) units, deterministic (same units every re-run)
    select hkey, rs, rs_key
      from (select distinct hkey, rs, rs_key from current_rows)
    qualify row_number() over (order by md5(to_varchar(hkey) || '|' || rs || '|DM-A')) <= 100
),
sample_keys as (
    select distinct hkey from sample_units
),
sat_sample as (
    select c.*, row_number() over (order by c.hkey, c.rs, c.ldts) as sat_row_id
