    select * from (
    select MD5_BINARY(NULLIF(UPPER(TRIM(CAST(('HUB_POLICY|' || (nullif(trim("CONTRACT_ID"::varchar), ''))) AS VARCHAR))), '')) as hkey,
           'OPUS_BJAZ_SH_MEM_DTLS_EXTN' as rs_key,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as ldts,
           object_construct_keep_null(
               'MEMBER_SEQUENCE', to_varchar(("MEMBER_NO"::number)),
               'CUMMULATIVE_AMT', to_varchar(null),
               'CUMM_BONUS', to_varchar(null),
               'CUMM_BONUS_AMT_COMP', to_varchar(null),
               'CUMM_BONUS_AMT_WIDER', to_varchar(null),
